(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["es"] = {"ui":{"lead":"La gente no solo ha jugado a los juegos: también los ha pintado. Amplía 3300 años de pinturas y figuras y mira los detalles.","details":"Detalles","links":"Ver o jugar el juego","record":"Sobre la obra","game":"Juego","exhibit":"Colección","room":"Sala","room_chance":"Azar","hint":"Pellizca o usa la rueda para ampliar · arrastra para mover · toca un número","r_artist":"Autor","r_date":"Fecha","r_place":"Lugar","r_medium":"Técnica","r_size":"Tamaño","r_museum":"Museo","r_credit":"Procedencia","r_rights":"Imagen","met":"The Metropolitan Museum of Art","cc0":"Acceso abierto (dominio público)","metlink":"La obra en la web del museo","credit":"Imágenes: The Metropolitan Museum of Art, The Cleveland Museum of Art, The Art Institute of Chicago y el Rijksmuseum, acceso abierto (dominio público).","cma":"The Cleveland Museum of Art","aic":"The Art Institute of Chicago","rijks":"Rijksmuseum, Ámsterdam"},"nefertari":{"title":"La reina Nefertari jugando al senet","artist":"Nina de Garis Davies (facsímil)","date":"original h. 1290–1224 a. C. · facsímil 1921–22","place":"Egipto (Valle de las Reinas)","game":"Senet","medium":"Témpera sobre papel (facsímil a la mitad del tamaño)","p":["Nefertari fue la esposa principal de Ramsés II. Es una copia de una pintura de su tumba en el Valle de las Reinas, hecha dentro de la tumba en 1921–22; se copiaron incluso las grietas y las faltas del muro.","La reina, sentada ante un tablero, juega al senet contra un rival invisible. Pintado en una tumba, se cree que el juego significaba algo más que diversión: ganar el viaje hacia el más allá."],"spots":[["Dos clases de piezas","Sobre el tablero hay piezas puntiagudas y piezas en forma de carrete: una para cada jugador."],["La mano de la reina","Sus dedos van a tomar una pieza."],["Tablero y soporte","El tablero se ve de lado, por eso no se ven las casillas. Descansa sobre un soporte de patas finas."],["Su nombre","El nombre de la reina está escrito dentro de un óvalo, un cartucho."],["El rival invisible","Enfrente no hay nadie: la reina juega contra un rival que no se ve."]]},"hydria":{"title":"Aquiles y Áyax jugando a un juego de tablero (hidria)","artist":"Atribuida al Grupo de Leagros","date":"h. 510 a. C.","place":"Grecia (Ática)","game":"Un juego de dados","medium":"Terracota (figuras negras)","p":["Durante el asedio de Troya, dos héroes griegos, Aquiles y Áyax, matan el tiempo ante un tablero. La escena la inventó hacia 540 a. C. el alfarero y pintor Exequias; su original se conserva en un ánfora de los Museos Vaticanos.","El tema gustó muchísimo entre 540 y 480 a. C., y se conocen más de 150 ejemplos. En esta hidria, la diosa Atenea está en el centro. Los héroes juegan a un juego en el que las piezas avanzan según la tirada de los dados."],"spots":[["Atenea","La diosa Atenea está de pie entre los dos."],["El héroe de la izquierda","Todavía con la lanza en la mano, se inclina sobre el tablero."],["El héroe de la derecha","Tampoco ha dejado las armas: un rato de juego en plena guerra."],["El tablero","El bloque bajo entre ambos es el tablero."],["El hombro","En el hombro de la vasija parte un carro."]]},"liubo":{"title":"Pareja de figuras sentadas jugando al liubo","date":"siglo I a. C. – siglo I d. C.","place":"China (dinastía Han)","game":"Liubo","medium":"Loza con pigmento","p":["Dos jugadores de liubo, la gran afición de la China Han. Figuras así se ponían en las tumbas con el deseo de que los placeres de la vida siguieran tras la muerte.","En la foto, entre ellos están el tablero de liubo y las piezas de hueso de la colección de este museo. Las figuras captan un momento dramático de una partida reñida."],"spots":[["El tablero de liubo","Es el mismo tablero que «Tablero y piezas de liubo» de la colección: mira las marcas en T, L y V."],["El jugador de la izquierda","Estudia el tablero con calma."],["El jugador de la derecha","Mano en alto y boca muy abierta: ¿acaba de hacer una jugada ganadora?"],["Piezas en el tablero","Las piezas de hueso están a ambos lados del tablero."],["Piezas fuera del tablero","Hay más piezas en el suelo."]]},"shahnama":{"title":"«Buzurjmihr descifra el juego indio del ajedrez», del Shahnama del sah Tahmasp","artist":"Pintura atribuida a ʿAbd al-Vahhab","date":"h. 1530–35","place":"Irán (Tabriz)","game":"Ajedrez","medium":"Acuarela opaca, tinta, plata y oro sobre papel","p":["Una escena del poema épico de Ferdousí, el Shahnama (Libro de los reyes). El rey de la India envía un emisario con un tablero y piezas de ajedrez y desafía al rey persa Nushirvan: si descubre cómo se juega, la India pagará tributo.","Solo el joven sabio Buzurjmihr lo resuelve a tiempo. En el Shahnama, Persia envía después el backgammon a cambio, y los indios no logran resolverlo. El rey y los cortesanos miran fijamente el tablero y a los jugadores."],"spots":[["El tablero","Las piezas están sobre un tablero cuadriculado, tan pequeñas que cuesta distinguir sus formas."],["El rey Nushirvan","En su trono, espera a ver resuelto el enigma."],["Alrededor del tablero","Los jugadores se inclinan sobre el tablero."],["Los versos","Los recuadros de arriba y abajo llevan versos de Ferdousí."],["Los cortesanos","Hombres con turbantes de altas varillas rojas miran de pie."]]},"chaupar":{"title":"Shiva y Parvati jugando al chaupar, de una serie del Rasamanjari","artist":"Devidasa de Nurpur","date":"1694–95","place":"India (Basohli, Jammu)","game":"Chaupar (pariente del antepasado del Ludo)","medium":"Acuarela opaca, tinta, plata y oro sobre papel","p":["Una página de una serie que ilustra el Rasamanjari, un poema amoroso sánscrito del siglo XV. El dios Shiva y su esposa Parvati se sientan sobre una piel de tigre ante un tablero en forma de cruz.","Shiva acaba de quitarle a Parvati un collar con trampas, y ella le suplica. Color atrevido, una profundidad espacial ambigua, y el color y el gesto usados por su significado: son los rasgos de la escuela de Basohli."],"spots":[["El tablero en cruz","El chaupar y el pachisi se juegan en un tablero con esta forma de cruz."],["Barras blancas en el tablero","Probablemente los dados largos (pasa) del chaupar."],["Shiva","De cuerpo blanco, con una serpiente al cuello."],["Parvati","Con la mano tendida, pide que le devuelva el collar."],["La piel de tigre","Los dos están sentados sobre una piel de tigre."]]},"shogi":{"title":"Una joven y un joven jugando al shōgi («Chūnagon Kanesuke», de los Treinta y Seis Inmortales de la Poesía)","artist":"Suzuki Harunobu","date":"h. 1767–69","place":"Japón (Edo)","game":"Shogi","medium":"Xilografía (nishiki-e)","p":["Una estampa de una serie que alude a los Treinta y Seis Inmortales de la Poesía; esta representa al poeta Chūnagon Kanesuke. Una noche de verano, junto a una mosquitera, una joven y un joven juegan al shogi.","Harunobu fue el artista que popularizó las estampas a todo color, impresas con muchas planchas. Hasta las piezas del tablero están dibujadas con detalle."],"spots":[["Un tablero de shogi con patas","Un tablero grueso con patas, como los de hoy."],["Una cajita","Probablemente la caja de las piezas."],["La mosquitera","Cuelga una mosquitera verde: es una noche de verano."],["El farol","Una lámpara de pie ilumina el tablero."],["El poema","El recuadro en forma de nube lleva el nombre del poeta y un poema."]]},"sugoroku":{"title":"Dos jóvenes jugando al sugoroku","artist":"Utagawa Toyokuni I","date":"periodo Edo (finales del s. XVIII – inicios del s. XIX)","place":"Japón (Edo)","game":"Ban-sugoroku (pariente del backgammon)","medium":"Díptico de xilografías","p":["Dos estampas unidas en una imagen ancha: unas jóvenes reunidas en una sala disfrutan de una partida de ban-sugoroku. El juego es pariente del backgammon, de la misma línea que el tablero de sugoroku del Shōsōin de esta colección.","Sobre el tablero hay piedras blancas y negras, y la joven de la derecha sostiene un cubilete para agitar los dados. Por la ventana se ve el monte Fuji."],"spots":[["El tablero","Piedras blancas y negras sobre sus casillas alargadas."],["El cubilete","En él se agitan los dados."],["Piedras fuera del tablero","¿Ya sacadas, o aún sin entrar?"],["El monte Fuji","El Fuji tras la ventana."],["La unión","Aquí se juntan las dos estampas."]]},"eakins":{"title":"Los jugadores de ajedrez","artist":"Thomas Eakins","date":"1876","place":"Estados Unidos (Filadelfia)","game":"Ajedrez","medium":"Óleo sobre tabla","p":["En el salón de una casa de Filadelfia, dos amigos juegan al ajedrez mientras el padre del artista, Benjamin Eakins, mira. Eakins aprendió su cuidadosa construcción del espacio y su detalle preciso de su maestro en París, Gérôme.","En 1881, Los jugadores de ajedrez fue la primera obra que el Metropolitan aceptó como donación de un artista vivo."],"spots":[["Las piezas","En la sala en penumbra, las piezas del tablero destacan con la luz."],["El padre del artista","De pie, mirando la partida: Benjamin Eakins."],["El jugador de la derecha","El pintor George W. Holmes, amigo del padre del artista."],["El cajón","Una inscripción latina: «El hijo de Benjamin Eakins pintó esto en el 76»."],["Sobre la chimenea","Una reproducción de un cuadro de Gérôme, el maestro de Eakins."],["El gato","En el suelo, solo el gato parece no interesarse por la partida."]]},"weiqi":{"title":"Plato con inmortales jugando al weiqi","artist":"Anónimo","date":"1425–36 (dinastía Ming, periodo Xuande)","place":"China","game":"Go (weiqi)","medium":"Laca tallada roja y verde","size":"Alt. 3,5; anch. 14,9; long. 23,5 cm","credit":"Donación de Florence y Herbert Irving, 2015","p":["Un plato de laca tallada: se aplicaron decenas de capas y luego se tallaron; bajo la roja hay una capa verde, y la profundidad del corte hace aparecer los colores. Dentro del borde lobulado, unos inmortales juegan al go bajo un pino.","En China existe la leyenda de Lanke, el «mango de hacha podrido»: el leñador Wang Zhi observó a unos inmortales jugar al go en la montaña y, al volver en sí, había pasado tanto tiempo que el mango de su hacha se había podrido. Los inmortales ante el tablero eran un tema muy querido. Quién es la figura de pie, los registros no lo dicen."],"spots":[["El tablero","El tablero de go entre los dos inmortales, tallado hasta en sus líneas."],["Los inmortales jugando","Dos figuras sentadas junto a las rocas, en torno al tablero."],["La figura de pie","Una figura de pie algo apartada. Recuerda al leñador de la leyenda, pero no se sabe quién es."],["La luna","Una luna redonda en el cielo (o quizá el sol)."],["El pino","Un pino de ramas extendidas, árbol que suele evocar la longevidad y la tierra de los inmortales."],["El borde de peonías","Grandes peonías y hojas talladas alrededor del borde."]]},"webb":{"title":"Los jugadores de backgammon (armario)","artist":"Philip Webb (diseño), Edward Burne-Jones (pintura), Morris, Marshall, Faulkner & Co. (fabricación)","date":"1861","place":"Gran Bretaña (Londres)","game":"Backgammon","medium":"Pino pintado, óleo sobre cuero, latón, cobre","size":"Alt. 185,4; anch. 114,3; prof. 53,3 cm","credit":"Rogers Fund, 1926","p":["Uno de los primeros muebles de la empresa que William Morris fundó con unos amigos en 1861. Sobre el cuero de las puertas, un hombre y una mujer vestidos a la medieval juegan al backgammon, pintados al óleo. Se expuso en la Exposición Internacional de Londres de 1862.","Resume el propósito de Arts and Crafts de borrar la frontera entre las bellas artes y las artes aplicadas. El fondo de cuero está punteado con diminutos golpes, una técnica medieval."],"spots":[["El tablero","El tablero de backgammon sobre la mesa, entre los dos."],["El hombre","Un joven, con una ficha en la mano, estudia el tablero."],["La mujer","Frente a él, una mujer con una ficha (o un cubilete)."],["Flores a sus pies","A los pies de los jugadores crecen flores."],["Cuero punteado","El fondo de cuero está punteado con finos golpes que atrapan la luz."],["Bandas de rombos","Bandas de rombos sobre oro enmarcan las puertas arriba y abajo."]]},"liberale":{"title":"Los jugadores de ajedrez","artist":"Liberale da Verona","date":"h. 1475","place":"Italia (Verona)","game":"Ajedrez","medium":"Temple sobre tabla","size":"34,9 × 41,3 cm","credit":"Colección Maitland F. Griggs, legado de Maitland F. Griggs, 1943","p":["Fragmento del frente de un cassone, el arcón decorado que guardaba el ajuar de una novia en la Italia del Renacimiento. Liberale fue conocido también por iluminar los cantorales de la catedral de Siena.","Muestra un momento de una historia de amor no identificada. En el fragmento compañero, una doncella en una ventana parece invitar a un joven a entrar; aquí los dos juegan al ajedrez. Según el museo, ella está a punto de perder. El ajedrez era una imagen favorita del cortejo en la literatura amorosa de la época."],"spots":[["El tablero","Un tablero rojo y blanco con piezas oscuras; la partida parece cerca del final."],["El joven","Alarga la mano hacia el tablero y parece a punto de ganar."],["La doncella","Sentada enfrente; en el panel compañero lo llama desde una ventana."],["La ventana","Tras la ventana abierta, una colina y el cielo."],["Jóvenes mirando","Hombres de brazos cruzados siguen la partida."],["Damas mirando","Mujeres que observan la partida tras la columna."]]},"mirror":{"title":"Estuche de espejo con una pareja jugando al ajedrez","artist":"Anónimo","date":"1325-1350","place":"Francia (París)","game":"Ajedrez","medium":"Marfil","size":"Diámetro 10,2 cm","credit":"Compra con el Fondo J. H. Wade, 1940","p":["Este disco de marfil del tamaño de la palma de la mano cubría un espejo de mano. En el París del siglo XIV, un espejo de metal pulido se guardaba entre dos placas de marfil y se llevaba encima; marfiles tallados como este eran lujos apreciados por cortesanos y aristócratas.","Dentro de una tienda con cortinas, un joven y una dama juegan al ajedrez. En los relatos medievales, el ajedrez representaba a la vez el amor y la guerra. Se ha propuesto que la pareja sea Tristán e Isolda, o Lanzarote y Ginebra, pero nadie lo sabe. El museo pregunta a sus visitantes: ¿quién crees que va ganando?"],"spots":[["El tablero","Un tablero sobre una mesa de un solo pie, con algunas piezas."],["El joven","Alarga la mano para hacer su siguiente jugada."],["La dama","Una mujer con toca; la punta de sus dedos toca una pieza."],["La mano cerrada","Su otra mano, cerrada, descansa en el regazo. ¿Guarda una pieza que ha capturado?"],["La tienda","Cortinas recogidas a ambos lados, escenario frecuente del ajedrez en los estuches de espejo."]]},"morris":{"title":"Un tablero de juego (el molino)","artist":"Peter Flötner","date":"1500-1546","place":"Alemania","game":"Molino (Nine Men’s Morris)","medium":"Xilografía","credit":"Fondo de Dotación Charles W. Harkness, 1923","p":["Una xilografía de Peter Flötner, uno de los escultores más dotados del Núremberg renacentista, que también diseñó ornamentos, muebles, modelos para orfebres y una baraja famosa por su sátira. Bajo el follaje en espiral se esconde el tablero del molino («Mühle» en alemán): tres cuadrados uno dentro de otro, unidos por el centro de cada lado.","El tablero tiene 24 puntos. Quien alinea tres piezas propias (un molino) retira una del rival. Grabados así servían también de modelo a los artesanos, y el museo expuso esta hoja en una muestra de modelos y diseños de orfebres. No consta si se jugaba sobre el papel o si se copiaba en madera o metal."],"spots":[["El cuadrado central","El cuadrado más interior, cubierto de fino entrelazado."],["Una esquina exterior","Esquina del cuadrado exterior: uno de los 24 puntos donde se colocan las piezas."],["Una esquina intermedia","Las esquinas del cuadrado del medio también son puntos."],["Las líneas de unión","Bandas que unen los tres cuadrados por el centro de cada lado; las piezas también se mueven por ellas."],["Un mascarón","Cartelas en espiral con rostros arriba, abajo y a los lados: ornamento de grutesco renacentista."],["La orla de vid","Hojas y frutos tallados en blanco sobre fondo negro."]]},"leifeng":{"title":"Juego de tablero de la pagoda Leifeng","artist":"Anónimo","date":"1736-1795 (periodo Qianlong)","place":"China","game":"Juego de carrera","medium":"Xilografía; tinta sobre papel","size":"31 × 29,8 cm","credit":"Compra con el Fondo J. H. Wade, 2025","p":["Una hoja impresa para jugar, del reinado del emperador Qianlong de la China Qing. Sus casillas reúnen a los personajes de la Leyenda de la Serpiente Blanca: el espíritu serpiente Bai Suzhen («la Dama Blanca»), su compañera Xiaoqing («la Pequeña Verde»), el joven Xu Xuan (Xu Xian en versiones posteriores) y el monje Fahai, que al final encierra a la Dama Blanca bajo la pagoda Leifeng, junto al Lago del Oeste.","El recorrido gira en espiral desde una casilla marcada 起馬, «salida», hasta la pagoda del centro. Probablemente se corría por la historia con dados, como en el juego de la oca occidental; las reglas no se conservan. Según el museo, estas estampas en color se vendían en las ciudades y se colgaban en las paredes como parte de la cultura visual urbana, cada color impreso con su propia plancha tallada."],"spots":[["Salida","La casilla marcada 起馬, «salida»: probablemente el punto de partida."],["La Dama Blanca y la Pequeña Verde","El espíritu serpiente Bai Suzhen y su compañera Xiaoqing."],["Xu Xuan","El joven que se casa con la Dama Blanca."],["El monje Fahai","El monje que la encierra bajo la pagoda."],["La pagoda Leifeng","La pagoda junto al Lago del Oeste de Hangzhou, donde termina la historia."],["El centro","Una mujer sentada ante la pagoda y un hombre arrodillado: la última escena del relato y, quizá, la meta."]]},"tutinama":{"title":"El mono herido muerde la mano del príncipe, su compañero de ajedrez (del Tuti-nama, Cuentos de un loro)","artist":"Dasavanta","date":"h. 1560","place":"India (corte mogol de Akbar)","game":"Ajedrez","medium":"Témpera, tinta y oro sobre papel","size":"20 × 14,2 cm (pintura 10,2 × 10,6 cm)","credit":"Donación de la Sra. A. Dean Perry, 1962","p":["Una ilustración del Tuti-nama, los «Cuentos de un loro», hecho en la corte del emperador mogol Akbar. Es uno de los relatos con que una madre loro advierte a sus polluelos contra las amistades con otras especies, como los cachorros de zorro. En él, un mono que jugaba bien al ajedrez solía jugar con un príncipe.","Un día, delante de unos invitados, el mono hizo una broma grosera y el príncipe le dio una bofetada; el mono le mordió la mano. Fuera, a la derecha, los criados preparan la comida mientras los invitados miran asombrados. Una inscripción abajo nombra a Dasavanta, que llegaría a ser uno de los maestros más célebres de la corte mogol; de joven puso una capa de azul frío bajo su pintura."],"spots":[["El mono","Muerde la mano del príncipe, su compañero de ajedrez."],["El príncipe","El príncipe mordido."],["El tablero","Un tablero de casillas rojas en el suelo."],["Los invitados asombrados","Los invitados a la reunión."],["La comida","Criados que ponen ollas al fuego afuera."],["El texto persa","Arriba, la historia escrita en persa."]]},"teniers":{"title":"Partida de backgammon","artist":"David Teniers","date":"década de 1640","place":"Flandes","game":"Backgammon","medium":"Óleo sobre tabla, pasado a lienzo","size":"59 × 80,6 cm","credit":"Donación del Sr. y la Sra. Samuel D. Wise, 1943","p":["Una partida de backgammon con mucho en juego, pintada por el flamenco Teniers. El juego es muy antiguo: su forma moderna apareció en el siglo XV, y el nombre «backgammon» nació más o menos cuando se pintó este cuadro. En el siglo XVII era popularísimo y se jugaba a menudo por dinero.","Los mirones rodean a los dos jugadores, y junto a la pared alguien lleva la cuenta. Por las mujeres que miran —una se asoma a una ventana— el museo cree que la sala es el cuarto de juego de un burdel. Estas escenas solían llevar una moraleja: el juego de azar era necio, incluso perverso, y una pérdida de tiempo."],"spots":[["El tablero","Un tablero de backgammon abierto sobre la mesa, con la partida en marcha."],["El hombre de blanco","Un jugador de espaldas, alargando la mano hacia sus fichas."],["El hombre con la mano en la mejilla","Su rival, absorto."],["El tanteador","Un hombre marca una tabla en la pared: ¿los puntos o las apuestas?"],["La mujer en la ventana","Una mujer mayor que mira desde arriba."],["La sala del fondo","Al fondo, hombres beben junto a una joven."]]},"imari":{"title":"Plato con dos hombres jugando al go","artist":"Anónimo","date":"siglo XVIII","place":"Japón (periodo Edo)","game":"Go","medium":"Porcelana moldeada con esmaltes sobre cubierta (Hizen, estilo Imari)","size":"2,4 × 13,8 cm","credit":"Colección Severance y Greta Millikin, 1964","p":["En este pequeño plato cuadrado, dos hombres juegan al go bajo un pino: el de amarillo, sentado frente al tablero puesto en el suelo; su rival de verde, recostado en el árbol.","Es porcelana de Imari hecha en Hizen (hoy Saga y Nagasaki), y sus verdes recuerdan los esmaltes de Kutani. Se hizo para la exportación, cuando Japón ya había sustituido a China como principal proveedor de porcelana de Europa."],"spots":[["El tablero de go","Un tablero cuadriculado, puesto directamente en el suelo."],["El hombre de amarillo","Sentado frente al tablero."],["El hombre de verde","Su rival, recostado en el árbol y sonriendo."],["El pino","Un pino extiende sus ramas por encima."],["El marco rojo","Un marco rojo de esquinas cortadas rodea la escena."]]},"shoei":{"title":"Las cuatro artes (uno de un par de biombos)","artist":"atribuido a Kanō Shōei","date":"finales del siglo XVI–principios del XVII","place":"Japón (periodo Momoyama)","game":"Go","medium":"Uno de un par de biombos de seis hojas; tinta y color ligero sobre papel","size":"153 × 358,6 cm","credit":"Fondo John L. Severance, 1979","p":["Un biombo de seis hojas atribuido a Kanō Shōei, de la escuela Kanō. Con su pareja muestra las «cuatro artes» que se esperaban de un caballero culto chino: tocar el qin, jugar al qi (go), la caligrafía y la pintura. Aquí, caballeros chinos de alto rango y sus criados descansan en el campo bajo los pinos.","En el centro, dos hombres juegan al go mientras un tercero observa. Cerca, una mesa sostiene libros y un qin aún en su funda de tela, esperando a que lo toquen. La escena equilibra disfrute y formalidad. El museo señala que uno de los criados se distrae con el movimiento de un pez en el agua."],"spots":[["El tablero de go","Un tablero con patas; dos caballeros juegan frente a frente."],["Los caballeros","Dos jugadores y un tercero que mira."],["La mesa","Probablemente la mesa con los libros y el qin en su funda."],["Los criados","Sirvientes que esperan junto a la mesa."],["El criado distraído","Tumbado junto al agua, mira moverse un pez."],["El pino","Un gran pino extiende sus ramas sobre la escena."]]},"umaya":{"title":"Biombo de las caballerizas (go y shogi en la galería)","artist":"Anónimo","date":"Principios del siglo XVI","place":"Japón (periodo Muromachi)","game":"Go y shogi","medium":"Uno de una pareja de biombos de seis hojas; tinta, color y oro sobre papel","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Este biombo de seis hojas unidas es uno de una pareja. Los preciados caballos de las cuadras quizá sean el tema principal, pero en la galería de delante ocurren muchas cosas.","Allí la gente se desafía en dos juegos distintos: go a la izquierda y shogi a la derecha. Según el museo, el ambiente animado nace del contraste entre los caballos inquietos y la estrategia serena de los juegos. En Japón se creía que los monos protegían a los caballos, y a veces se tenían en las cuadras."],"spots":[["El tablero de go","Un tablero de líneas finas con piedras negras."],["Dos hombres con gorro negro","Hombres con alto eboshi negro: el de verde tiende la mano al tablero, el de rojo mira."],["El tablero de shogi","Un tablero de casillas grandes, muchas menos que en el de go."],["El rival que ríe","Un monje rapado coge una pieza mientras el hombre de enfrente se lleva la mano a la cabeza y ríe a carcajadas. ¿Alguien acaba de anotarse un tanto?"],["Un mono","Al final de la galería, ¿un mono con chaqueta roja?"],["Un caballo","Un caballo negro se encabrita, sujeto por sus cuerdas."]]},"goryeo":{"title":"Jarra con figuras jugando al go, de celadón con incrustaciones","artist":"Anónimo","date":"Siglo XIII","place":"Corea (dinastía Goryeo)","game":"Go (baduk)","medium":"Celadón con incrustaciones de engobe blanco y negro","size":"Alt. 20,4 cm, diám. 14,3 cm","credit":"Donación de John L. Severance, 1917","p":["Una jarra de celadón de Goryeo, con pico y asa. La incrustación —grabar líneas en el barro, rellenarlas de engobe blanco y negro y luego vidriar y cocer— era la especialidad de los alfareros de Goryeo; aquí, dentro de un marco redondo, dos figuras sentadas bajo un sauce resaltan en blanco.","Entre ellas hay un tablero, y el museo compara la escena con las imágenes de partidas de go —baduk en coreano—. Tocar la cítara, el go, la caligrafía y la pintura eran las «cuatro artes» del letrado culto, y sus elegantes reuniones se convirtieron también en motivos para los artesanos. El celadón coreano con figuras humanas es poco común."],"spots":[["El tablero","El tablero entre los dos, un cuadrado blanco."],["La figura de la izquierda","Sentada frente al tablero."],["La figura de la derecha","El rival, sentado enfrente."],["El sauce","Ramas de sauce cuelgan sobre ellos, dibujadas con engobe negro."],["El marco de nubes","Volutas como nubes rodean el marco redondo."],["El craquelado","Finas grietas en el vidriado. Se forman al enfriarse, porque el barro y el vidriado encogen de forma distinta."]]},"kangra":{"title":"Pareja jugando al chaupar en una terraza","artist":"Anónimo","date":"h. 1790–1800","place":"India (Pahari, escuela de Kangra)","game":"Chaupar","medium":"Dibujo con boceto previo en ocre rojo","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Dibujo de un artista de Kangra, en las colinas pahari al pie del Himalaya. El primer boceto se hizo en rojo (ocre rojo) y luego se precisó en negro. Sin color encima, se puede seguir cada línea de las figuras y sus objetos.","Un hombre y una mujer, sentados en una terraza a ambos lados de un tablero en cruz, juegan al chaupar, un antiguo juego de carreras indio sobre la misma cruz que el parchís (pachisi), que se mueve lanzando dados largos (pasa). Las casillas aún no están dibujadas en el tablero. Unas sirvientas atienden a la pareja."],"spots":[["El tablero en cruz","Un tablero en forma de cruz, en el suelo. Sus casillas aún no están dibujadas."],["La mujer","Con la palma hacia arriba: ¿a punto de lanzar los dados?"],["El hombre","Turbante con penacho; tiende la mano hacia el tablero."],["La sirvienta de la izquierda","Sostiene un frasquito y extiende un paño."],["La sirvienta de la derecha","Sostiene un utensilio de mango largo y un recipiente pequeño."],["El boceto rojo","Alrededor del turbante, el boceto rojo asoma bajo las líneas negras."]]},"vuillard":{"title":"La partida de damas (de Paisajes e interiores)","artist":"Édouard Vuillard","date":"1899","place":"Francia","game":"Damas","medium":"Litografía en color (estado III/III); impresa por Auguste Clot, editada por Ambroise Vollard","size":"Imagen 33 × 25,7 cm (hoja 38 × 30,8 cm)","credit":"Donación del Hanna Fund, 1951","p":["Ambroise Vollard, marchante de pintura impresionista, fue también un importante editor de grabados. En 1895 encargó a Pierre Bonnard un álbum de 12 litografías en color y después publicó muchos más, entre ellos Paisajes e interiores de Vuillard, impreso por el maestro impresor Auguste Clot.","Bonnard y Vuillard formaban parte de los nabis —«profetas» en hebreo—, que buscaban un arte nuevo en el que la forma y el color expresaran por sí mismos el sentimiento, y que amaban las escenas de la vida urbana y familiar. En una habitación llena de motivos, dos hombres se enfrentan ante un tablero de damas mientras una mujer, de pie, observa. En francés el juego se llama «dames»; la nota a lápiz abajo a la izquierda dice «partie de dames», una partida de damas."],"spots":[["El tablero","Un pequeño tablero a cuadros, con las piezas colocadas."],["El hombre de la izquierda","Un hombre con barba extiende la mano sobre el tablero."],["El hombre de la derecha","Su rival, inclinado sobre el tablero en un sillón, medio oculto por la mujer de pie."],["La mujer de pie","Con la mano en la barbilla, sigue la partida."],["La lámpara","Una lámpara junto a la pared. El papel pintado y la tapicería están llenos de motivos."],["La nota a lápiz","Abajo a la izquierda, a lápiz: «partie de dames», una partida de damas."]]},"talbot":{"title":"Los jugadores de ajedrez (fotografía temprana)","artist":"Atribuida a William Henry Fox Talbot","date":"h. 1843–47","place":"Inglaterra","game":"Ajedrez","medium":"Copia a la sal","size":"19,9 × 15 cm","credit":"Adquirida con fondos del Sr. y la Sra. Everett Kovler","p":["El procedimiento negativo-positivo inventado por Talbot, con las copias ilimitadas que hizo posibles, dominó la fotografía hasta la era digital. Sus primeros experimentos muestran a la vez su interés científico y su ambición artística, y los estudiosos han confirmado que tomó diez o más vistas de jugadores de ajedrez.","Sin embargo, esta quizá no sea suya: esta copia y otras de la misma escena no están firmadas y usan un papel distinto del habitual de Talbot. Los retratados serían el fotógrafo Antoine Claudet y el ayudante de Talbot, Nicolaas Henneman; estudios recientes sugieren que las imágenes se hicieron en el estudio de Claudet, pasaron a Henneman y llegaron a Talbot como parte del pago de una deuda (nota del museo)."],"spots":[["El tablero","El tablero sobre la mesa, con las piezas en fila."],["El hombre de chistera","Sin quitarse el sombrero, toma una pieza."],["El pensativo","Con la mano en la barbilla, el rival estudia el tablero."],["La cortina","Una cortina al fondo: ¿un decorado para la toma?"],["Otro sombrero","Otra chistera descansa sobre el soporte de la derecha."]]},"pvl":{"title":"Hombres jugando a los dados","artist":"Maestro PVL","date":"h. 1520","place":"Países Bajos","game":"Dados","medium":"Grabado a buril sobre papel","size":"9,4 × 9,4 cm (circular)","credit":"Colección Charles Hack y Hearn Family Trust, adquirida en 2023","p":["Obra de un grabador anónimo activo en los Países Bajos a principios del siglo XVI, llamado Maestro PVL por el monograma «PVL» grabado abajo a la izquierda. En un grabado redondo que cabe en la palma de la mano, finísimas líneas apretadas construyen la profundidad de la sala y la textura de la ropa.","Sobre la mesa hay dos dados. Un hombre inclinado y un joven con cuello de piel señalan y discuten, quizá por la cuenta. Detrás miran unas mujeres, y bajo la mesa hay una jarra de vino. Los dados van unidos al juego de apuestas desde la Antigüedad y fueron prohibidos una y otra vez."],"spots":[["Los dados","Dos dados rodando sobre la mesa."],["Las manos que señalan","Dos dedos se encuentran sobre la mesa: ¿una disputa por la cuenta?"],["El hombre del sombrero ancho","Inclinado hacia delante; sus mangas acuchilladas y abullonadas eran la moda de la época."],["El joven del cuello de piel","Un joven con gran sombrero y cuello de piel."],["Las mujeres que miran","Unas mujeres observan la partida desde atrás."],["El monograma","«PVL» abajo a la izquierda: la única pista del nombre del artista."]]},"kiyohiro":{"title":"Jugadoras de sugoroku","artist":"Torii Kiyohiro","date":"h. 1750","place":"Japón (periodo Edo)","game":"Ban-sugoroku","medium":"Xilografía en color (benizuri-e), ōban; editor Urokogataya","size":"43,5 × 29,3 cm","credit":"Colección Clarence Buckingham","p":["Torii Kiyohiro fue un artista de ukiyo-e activo entre hacia 1737 y 1776. Esta es una benizuri-e, impresa con pocas planchas de color —rosa beni, verde y similares— en los años anteriores a la aparición, en 1765, de las nishiki-e a todo color.","El juego sobre el soporte negro es el ban-sugoroku: dos jugadores tiran los dados y mueven fichas blancas y negras, y gana quien saque antes todas las suyas. Es de la misma familia que el backgammon, y los grabados ukiyo-e muestran a menudo a mujeres disfrutándolo. Detrás, una mujer fuma una pipa larga y mira."],"spots":[["El tablero","Un tablero de sugoroku sobre su soporte, con fichas blancas y negras."],["La figura de la izquierda","Alarga la mano para mover una ficha."],["La mujer de la derecha","Inclinada sobre el tablero, la rival estudia las fichas."],["La mujer de la pipa","Con una larga pipa kiseru, sigue la partida desde atrás."],["La mano alzada","La mujer de la derecha sostiene algo pequeño y negro: ¿el cubilete?"],["La firma","«Torii Kiyohiro hitsu», con el sello del editor Urokogataya."]]},"ingram":{"title":"El juego del ajedrez chino","artist":"John Ingram, según François Boucher","date":"1741–63","place":"Francia (París)","game":"Xiangqi","medium":"Aguafuerte y buril","size":"Hoja 39,4 × 27,7 cm (plancha 24,5 × 16,4 cm)","credit":"Colección Elisha Whittelsey, 1966","p":["Un dibujo del pintor francés François Boucher grabado por el londinense John Ingram. Ingram se trasladó a París y, entre 1741 y 1763, hizo una serie de estampas según las chinoiseries de Boucher, la China que imaginaban los europeos. El título dice «LE JEU D'ECHETS CHINOIS», el juego del ajedrez chino.","Una mujer de peinado alto mueve una pieza en el tablero que tiene sobre las rodillas mientras un niño pequeño mira. Se considera que el juego es el xiangqi, pero las piezas reales del xiangqi son todas discos planos, y aquí hay piezas altas junto a otras pequeñas y cuadradas. La palmera y la figura sentada sobre la urna pertenecen menos a China que al país lejano con que soñaba la Europa de entonces."],"spots":[["Tablero y piezas","El tablero sobre sus rodillas, con piezas altas y cuadradas. Las piezas reales del xiangqi son discos planos."],["La mano en la pieza","Su mano derecha mueve una pieza."],["La mejilla en la mano","Con la mano izquierda en la barbilla, mira el tablero."],["El niño que mira","Un niño de pie junto al tablero sigue la partida."],["La figura de la urna","Una figura sentada con las piernas cruzadas sobre una gran urna."],["Título y nombres","«Dessiné par Fr. Boucher», «Gravé par Ingram» y el título «LE JEU D'ECHETS CHINOIS»."]]},"posada":{"title":"Juego de la Oca","artist":"José Guadalupe Posada","date":"1909","place":"México","game":"Juego de la oca","medium":"Grabado en relieve sobre zinc, impreso en papel","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["Una hoja para jugar hecha por el grabador mexicano Posada —famoso por sus calaveras— para el editor de la Ciudad de México Antonio Vanegas Arroyo. La cinta de abajo a la izquierda dice «JUEGO DE LA OCA», y el recorrido gira en espiral desde la casilla 1 hasta la 63, en el centro.","En el centro va impresa la EXPLICACION: si en la primera tirada salen 5 y 4 se va al 26, y con 6 y 3 al 53. Quien cae en una oca (un ave) vuelve a contar lo mismo; en la Venta (19) se esperan dos tiradas; en el Poso (31) y la Carcel (52) se queda hasta que otro lo saque; el Laberinto (42) devuelve al 39 y la Muerte (58) al principio. Hay que llegar justo al 63. Además se pagaban apuestas al caer en ciertas casillas: era también un juego de apuestas."],"spots":[["La explicación","La «EXPLICACION» del centro: qué hace cada casilla y cuándo se paga la apuesta."],["La casilla 1","La salida. Desde aquí el recorrido gira hacia el centro."],["El pozo (31)","Un pozo como una fuente. Quien cae se queda hasta que llega otro."],["La muerte (58)","La casilla de la calavera: se vuelve al principio."],["La cinta del título","«JUEGO DE LA OCA» en la cinta de abajo a la izquierda, con niños jugando debajo."],["El nombre del editor","La cinta de la diosa dice «IMPRENTA DE A. VANEGAS ARROYO», la casa que publicó muchos grabados de Posada."]]},"jintile":{"title":"Placa con mujeres jugando a un juego de tablero","artist":"Anónimo","date":"Siglo XIII","place":"China (dinastía Jin)","game":"Juego de tablero (probablemente go)","medium":"Barro cocido (relieve moldeado)","size":"Alt. 27,3 cm, anch. 24,8 cm, prof. 5,4 cm","credit":"Compra, donativos de Friends of Asian Art, 2002","p":["Una placa en relieve hecha bajo los Jin (1115–1234), la dinastía del pueblo yurchen que gobernó el norte de China. Bajo un árbol en flor, dos mujeres se sientan frente a frente en una tarima con un tablero entre ellas.","El tablero tiene una cuadrícula fina, así que probablemente juegan al go. La de la derecha se inclina y señala el tablero mientras la de la izquierda mira. Muchas tumbas de época Jin del norte de China se revestían con ladrillos en relieve con escenas de la vida diaria, y esta placa probablemente decoraba una de ellas."],"spots":[["El tablero","Un tablero de cuadrícula fina, probablemente de go."],["La mano que señala","La mujer de la derecha señala el tablero. ¿Su próxima jugada?"],["La mujer de la izquierda","Con el pelo recogido en alto, mira el tablero."],["La mujer de la derecha","Inclinada sobre el tablero."],["El árbol en flor","Ramas de un árbol en flor se extienden sobre ellas."],["La tarima","La tarima donde se sientan, con un faldón ondulado entre las patas."]]},"kyosai":{"title":"Un pedo arruina una partida de go (de un álbum de bocetos)","artist":"Kawanabe Kyōsai","date":"Mediados o finales del siglo XIX","place":"Japón (periodos Edo a Meiji)","game":"Go","medium":"Una doble página de un álbum plegable de 26 dobles hojas; tinta y color sobre papel","size":"Álbum (cerrado) 28 × 18 cm","credit":"Donación de Anne y Anthony d’Offay en honor de Evan Turner","p":["Una escena de un álbum de bocetos de Kawanabe Kyōsai (1831–1889), pintor activo desde el final del shogunato hasta la era Meiji, dibujada con trazos rápidos y libres en las páginas de un álbum plegable. Formado en la exigente técnica de la escuela Kanō, Kyōsai fue también muy querido por sus demonios, caricaturas y sátiras.","El título del museo lo dice todo: «Un pedo arruina una partida de go». A la izquierda, un hombre con gorro negro se agacha; a la derecha, el tablero sale volando, los cuencos dejan caer una lluvia de piedras y su rival cae de espaldas. Una partida seria arruinada de un solo golpe: Kyōsai recoge con su pincel veloz el viejo humor japonés del pedo, presente ya en rollos medievales."],"spots":[["El hombre del gorro negro","Agachado, con el trasero hacia fuera: ¿el causante del lío?"],["El tablero volando","El tablero cuadriculado sale despedido en diagonal."],["Cuencos y piedras","Dos cuencos se vuelcan y las piedras caen como lluvia."],["El abanico","Un abanico abierto sale volando junto al tablero."],["El rival derribado","Tumbado de espaldas, con los ojos muy abiertos."],["El trazo","Líneas de tinta enérgicas, como hechas de una vez sin boceto."]]},"yokuts":{"title":"Bandeja para juegos de azar","artist":"Tejedora yokuts (nombre desconocido)","date":"h. 1900","place":"Estados Unidos (cerca de Dunlap, California)","game":"Huuchuish (dados de cáscara de nuez)","medium":"Fibras vegetales (cestería en espiral)","size":"Alt. 5,1 cm, diám. 61 cm","credit":"Adquirida con fondos de la Sra. de Leonard S. Florsheim Jr.","p":["Muchos pueblos indígenas de California practicaban juegos de azar. Esta bandeja servía para el huuchuish, un juego de dados exclusivo de las mujeres: se lanzaban ocho dados de cáscara de nuez sobre la bandeja y se llevaba la cuenta con palitos.","El diseño circular tejido en la bandeja muestra el propio juego: los dados, los palitos de cuenta y las jugadoras (nota del museo). Es un utensilio de juego que lleva la imagen de su propio juego. En la fotografía hay dados de cáscara de nuez sobre la bandeja y alrededor."],"spots":[["Las jugadoras","Figuras que recorren el borde: quienes participan en el juego."],["Palitos de cuenta","Haces de rayitas verticales: los palitos para llevar la cuenta."],["Motivos redondos","Pequeños motivos redondos: ¿los dados?"],["Un dado de nuez","Un dado de cáscara de nuez. Se lanzaban ocho sobre la bandeja."],["La banda de triángulos","Una banda de triángulos oscuros da toda la vuelta."],["El centro","La espiral del tejido sale del centro, rodeada por un círculo de trazos."]]},"hokkei":{"title":"Ushiwakamaru vence a Benkei al sugoroku","artist":"Totoya Hokkei","date":"h. 1825","place":"Japón (periodo Edo)","game":"Ban-sugoroku","medium":"Surimono (xilografía en color, shikishiban)","size":"21,8 × 19,1 cm","credit":"Donación de Helen C. Gunsaulus","p":["Un surimono de Totoya Hokkei (1780–1850), discípulo de Hokusai. Los surimono eran estampas de encargo privado —a menudo de círculos de poesía, con sus propios versos— y se acababan con más lujo que el ukiyo-e comercial, con buen papel y pigmentos metálicos.","Ushiwakamaru, nombre de niñez del héroe Minamoto no Yoshitsune, y el gigantesco monje guerrero Benkei. Su famoso encuentro fue un duelo en el puente Gojō de Kioto, pero aquí el combate se convierte en una partida de sugoroku: el muchacho se sienta tranquilo tras el tablero y Benkei, con la alabarda a la espalda, se rasca la cabeza derrotado. Parece una recreación juguetona."],"spots":[["El tablero de sugoroku","Un tablero en forma de caja con piezas blancas y negras."],["Benkei rascándose la cabeza","Con armadura completa, el vencido se rasca la cabeza."],["Ushiwakamaru","El joven héroe, sentado tras el tablero."],["La alabarda","La hoja de la gran naginata de Benkei."],["El poema","Versos arriba a la derecha, probablemente del círculo que encargó la estampa."],["La firma","La firma de Hokkei en la cartela de abajo a la derecha."]]},"vorsterman":{"title":"Jugadores de chaquete (escena nocturna)","artist":"Lucas Emil Vorsterman, según Adam de Coster","date":"h. 1630","place":"Flandes (Amberes)","game":"Backgammon","medium":"Grabado a buril sobre papel marfil","size":"Imagen 25,5 × 34,4 cm","credit":"Colección Bernard F. Rogers","p":["Adam de Coster fue un destacado pintor de escenas nocturnas a la luz de las velas en la Amberes de hacia 1630, cuando Vorsterman, en la misma ciudad, grababa obras de contemporáneos populares. Discípulo de Rubens, Vorsterman se enemistó con su maestro y se fue a Inglaterra, tras lo cual hizo grabados más contrastados, estilizados y caravaggescos como este.","En torno a una mesa en un cuarto oscuro, unos hombres se reúnen ante un tablero de backgammon. Siguiendo el manejo de la luz de De Coster, dos velas iluminan los rostros alrededor de la mesa (nota del museo). A la derecha, un joven laudista nos mira."],"spots":[["El tablero","Un tablero de backgammon abierto como una caja sobre la mesa."],["La vela","Una vela en su candelero: su llama ilumina los rostros."],["El hombre de la pipa","Con sombrero ancho, fuma y mira la partida."],["El hombre de espaldas","Inclinado, con las manos en la mesa."],["El laudista","Un joven con un laúd que nos sonríe."],["Los nombres","«A. De Coster pi.» abajo a la izquierda, «Vorsterman» abajo a la derecha."]]},"zorn":{"title":"Jugadores de ajedrez","artist":"Anders Zorn","date":"1891","place":"Suecia","game":"Ajedrez","medium":"Aguafuerte sobre papel verjurado marfil","size":"Imagen 13,5 × 9,6 cm (plancha 13,9 × 10 cm)","credit":"Colecciones de aguafuertes de Anders Zorn de Wallace L. DeWolf y Charles Deering","p":["Un aguafuerte del artista sueco Anders Zorn (1860–1920), que alcanzó fama internacional con sus retratos al óleo y a la acuarela y dejó también una gran obra grabada. La plancha no es mayor que una mano.","Bastan líneas rápidas y oblicuas superpuestas para que surjan del cobre un cuarto oscuro y dos personas. El hombre de delante, de espaldas, se inclina sobre el tablero; la figura de enfrente baja la vista, pensando la próxima jugada. Las piezas están dibujadas con trazos finos. No consta quiénes posaron."],"spots":[["Tablero y piezas","La zona clara de abajo es el tablero; los trazos cortos verticales, las piezas."],["El hombre de delante","De espaldas, se inclina sobre el tablero."],["El rival","Con la cabeza baja, mira el tablero."],["El fondo oscuro","El fondo del cuarto, hecho de líneas verticales."],["Líneas oblicuas","La chaqueta está hecha de trazos diagonales rápidos superpuestos."],["La firma","Firmado «Zorn» a lápiz bajo la plancha."]]},"harunobu-sugoroku":{"title":"Mirando la partida (sugoroku)","artist":"Suzuki Harunobu","date":"h. 1766","place":"Japón (periodo Edo)","game":"Ban-sugoroku","medium":"Xilografía en color (chūban, surimono)","size":"28,5 × 21 cm","credit":"Colección Clarence Buckingham","p":["Suzuki Harunobu (1725?–1770) fue la figura central cuando, hacia 1765, nacieron las nishiki-e, estampas a todo color impresas con muchas planchas. Esta es un surimono de edición privada, y sus colores suaves y superpuestos muestran la novedad.","En una sala con ciruelos en flor, dos muchachas juegan ante un tablero de sugoroku en forma de caja mientras una tercera, de pie, lo observa. Fichas blancas y negras ocupan el tablero; la de la izquierda mueve una y la de la derecha alarga la mano. La puerta corredera del fondo tiene pintados una cascada y unos pinos."],"spots":[["El tablero de sugoroku","Un tablero de ban-sugoroku en forma de caja, con fichas blancas y negras."],["La muchacha de la izquierda","Con un kimono de grullas de papel, mueve una ficha."],["La muchacha de la derecha","Inclinada, alarga la mano hacia el tablero."],["La espectadora","De pie, mira la partida con un objeto de mango largo en la mano."],["El ciruelo","Un ciruelo blanco extiende sus ramas desde arriba."],["La puerta pintada","Una puerta corredera pintada con una cascada y pinos."]]},"kota":{"title":"Maharao Kishor Singh II de Kota adorando a Krishna como Brij Rajji","artist":"Anónimo","date":"h. 1825","place":"India (Rajastán, Kota)","game":"Pachisi","medium":"Témpera de goma, plata y oro sobre papel","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["El soberano del pequeño estado principesco de Kota (r. 1819–28), vestido como sacerdote de la secta Pushti Marg, ofrece una lámpara de cinco llamas. En el pequeño santuario del altar hay imágenes de metal de Krishna flanqueado por dos consortes, un icono que solo se venera en Kota.","Del techo cuelgan muchas lámparas de vidrio, y en los escalones que suben al altar hay juguetes y juegos para entretener a Krishna y sus compañeros: elefantes de latón, vacas de plata, pelotas y un tablero de pachisi (nota del museo). La tela roja en forma de cruz es ese tablero: el pachisi ofrecido como juguete del dios."],"spots":[["El tablero de pachisi","La tela roja en cruz sobre los escalones: un tablero de pachisi."],["Elefantes","Dos elefantes de latón junto al tablero."],["Pelotas","Pelotas doradas en el escalón de arriba."],["Krishna","Las imágenes de Krishna y dos consortes en el santuario."],["El soberano y su lámpara","Vestido de sacerdote, ofrece una lámpara de cinco llamas."],["Lámparas de vidrio","Una multitud de lámparas cuelga del techo."]]},"coyote":{"title":"Juego del Coyote","artist":"Seguidor de José Guadalupe Posada","date":"Sin fecha","place":"México","game":"Coyote y gallinas (de la familia del zorro y los gansos)","medium":"Grabado en relieve sobre zinc, impreso en papel","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Una hoja para jugar, impresa en relieve sobre zinc como las que Posada hacía para las imprentas populares de la Ciudad de México. Arriba se lee «JUEGO DEL COYOTE»; alrededor, coyotes asaltan el gallinero y un hombre blande un palo para ahuyentar a uno. La franja de abajo dice «Propiedad de Ildefonso T. Orellana».","La EXPLICACION impresa abajo da las reglas: juegan dos personas, una con quince fichas llamadas Gallinas y otra con una, el Coyote. Las gallinas suben y caminan hacia los lados, pero nunca retroceden; el coyote se mueve en todos sentidos y se come una gallina saltando sobre ella si detrás hay lugar vacío. Las gallinas ganan si logran encerrar al coyote. Es el mismo juego de caza que el europeo del zorro y los gansos."],"spots":[["El lugar del coyote","La cabeza del coyote en el círculo central: allí empieza el coyote."],["Los lugares de las gallinas","Círculos con gallinas: allí se colocan sus fichas."],["La explicación","La «EXPLICACION»: fichas, movimientos y cómo se gana."],["El título","«JUEGO DEL COYOTE»."],["Un coyote tras una gallina","Abajo a la izquierda, un coyote va por una gallina."],["El hombre del palo","Arriba a la derecha, un hombre alza un palo contra un coyote."]]},"mons":{"title":"Chaquete por Mons (Bergen), 1709","artist":"Pieter Nolpe (plancha y editor)","date":"Plancha 1623–53; impresión h. 1709","place":"Países Bajos (Ámsterdam)","game":"Chaquete (juego de la familia del backgammon)","medium":"Aguafuerte, buril y verso tipográfico","size":"Hoja 35,8 × 18,6 cm (plancha 12,9 × 17,5 cm)","credit":"","p":["Cuatro hombres juegan al chaquete en una mesa. Según el registro del museo, las letras A–D señalan al duque de Marlborough, al elector de Baviera, al señor de Ouwerkerk y al duque de Villeroy. Es una sátira del asedio y la toma de Mons (Bergen en neerlandés) por los aliados a los franceses en 1709, presentada como una partida en la que se juega la ciudad. En la habitación del fondo (E), el rey Felipe V de España está con una mujer.","La plancha está firmada por Pieter Nolpe como autor y editor, pero Nolpe murió a principios de la década de 1650; probablemente se reimprimió una vieja plancha del siglo XVII añadiéndole letras y un verso nuevo. El poema empieza diciendo que el juego de los grandes señores es puro tiktak y verkeer (dos juegos de tablas) y luego se burla de cada jugador."],"spots":[["El tablero","El tablero de chaquete sobre la mesa: se juega una ciudad."],["A, Marlborough","De pie, mira el tablero: el general inglés de los aliados."],["B, el elector de Baviera","Sin sombrero, hundido en su silla."],["C, Ouwerkerk","Con sombrero de plumas: el general neerlandés."],["E, la habitación del fondo","Al fondo, Felipe V con una mujer en el dormitorio."],["El verso","Verso neerlandés impreso abajo, que se burla de los jugadores A a E."]]},"stembus":{"title":"La urna: un juego de la oca político","artist":"Johan Michaël Schmidt Crans (grabador)","date":"1867","place":"Países Bajos","game":"Juego de la oca (sátira)","medium":"Litografía","size":"66 × 50 cm","credit":"","p":["Una estampa satírica en forma de juego de la oca. Se publicó con el semanario De Nederlandsche Spectator, n.º 9, del 2 de marzo de 1867, junto con una hoja suelta de reglas (registro del museo). Las casillas llevan retratos de los ministros de entonces.","Se empieza en el Binnenhof, el parlamento de La Haya, y se termina en el centro, en la casilla 64, «Insulinde» —nombre poético de las Indias Orientales Neerlandesas—, donde cuelga de la isla de Java un retrato del ministro Pieter Mijer. Mijer había pasado de ministro de Colonias a gobernador general de las Indias, y el nombramiento desató una tormenta política. La casilla de más, una sobre las 63 habituales, está ahí probablemente por el chiste final."],"spots":[["La salida","El edificio de arriba a la izquierda: se empieza en el Binnenhof de La Haya."],["El retrato de Mijer","Casilla 63: un retrato enmarcado de Pieter Mijer, colgado de la isla con cuerdas."],["Insulinde 64","La isla y el número 64 en el centro: la meta."],["La urna","«DE STEMBUS» (la urna) abajo a la derecha: la caja del título."],["Los ministros","Los rostros de los ministros de entonces asoman en las casillas."],["El gallo","Un gallo en una casilla; no se sabe de qué se burla."]]},"koorai":{"title":"Coreanos ante un juego de tablero (del Nippon de Siebold)","artist":"James Erxleben (litógrafo), según un diseño de «Toioske»","date":"1832–52","place":"Países Bajos (Leiden) / gente de Corea","game":"Juego de tablero (probablemente go)","medium":"Litografía a tono, coloreada a mano","size":"Hoja 38 × 55,5 cm","credit":"Donación de F. G. Waller","p":["Una lámina de NIPPON, la gran obra que el médico de origen alemán Philipp Franz von Siebold publicó en Leiden a partir de lo que vio en la factoría neerlandesa de Nagasaki (1823–30). Lleva «TAB. I» arriba a la derecha y «KOORAI» (Corea) abajo, con «una familia de pescadores» en neerlandés y alemán. Erxleben la dibujó en la piedra; la lámina nombra al diseñador como «Toioske».","Cuatro hombres sentados en el suelo rodean un tablero; a la izquierda una mujer lleva de la mano a un niño, a la derecha un hombre de pie sostiene un palo largo y una bolsa. Delante hay un sombrero negro de ala ancha (gat). El tablero muestra una cuadrícula y piedras redondas, así que probablemente es go (baduk en coreano), aunque el registro solo dice «un juego de tablero»."],"spots":[["El tablero","Cuadrícula con piedras redondas: probablemente una partida de go."],["El sombrero negro","Un sombrero negro de ala ancha (gat) en el suelo."],["Madre e hijo","Una mujer con un niño de la mano mira la partida."],["El hombre de pie","De pie, con un palo largo y una bolsa."],["El hombre inclinado","Con chaqueta azul, mira el tablero."],["El título","«KOORAI» (Corea), con «una familia de pescadores» en neerlandés y alemán."]]},"cairo":{"title":"Gente en torno a un juego de tablero ante un café (El Cairo)","artist":"Délié & Béchard (Hippolyte Délié y Émile Béchard)","date":"h. 1869–90","place":"Egipto (El Cairo)","game":"Juego de tablero (probablemente ajedrez)","medium":"Copia a la albúmina","size":"10,8 × 16,4 cm","credit":"","p":["Una fotografía de Hippolyte Délié y Émile Béchard, fotógrafos franceses con estudio en El Cairo. El soporte lleva impreso el nombre del estudio, «junto al jardín de Ezbekiya», y «El Cairo (Egipto)». Los viajeros compraban fotos así como recuerdo de Egipto.","Unos hombres sentados en el suelo ante una tienda con una ventana de celosía rodean un tablero sobre un soporte bajo. Sobre el tablero hay piezas altas, así que probablemente es ajedrez (shatranj en árabe), aunque el registro del museo dice solo «un juego de tablero». Todos se quedan quietos para la larga exposición."],"spots":[["Tablero y piezas","El tablero sobre un soporte bajo, con piezas altas: probablemente ajedrez."],["La ventana de celosía","Una ventana con celosía de madera, típica de las casas antiguas de El Cairo."],["El hombre del bastón","Sentado con un bastón, mira la partida."],["La cesta","Una cesta tejida en el suelo."],["El niño que mira","Un niño se asoma al tablero desde atrás."],["El nombre del estudio","«AU JARDIN DE L’ESBÉKIEH» y «CAIRE (EGYPTE)» en el soporte."]]},"vanmour":{"title":"Reunión de armenios jugando a las cartas","artist":"Jean-Baptiste Vanmour","date":"h. 1720–37","place":"Imperio otomano (Estambul)","game":"Cartas","medium":"Óleo sobre lienzo","size":"44,5 × 58,5 cm","credit":"","p":["Nacido en Flandes, Vanmour llegó a Estambul en 1699 con el embajador de Francia y vivió en la ciudad hasta su muerte, pintando ceremonias de la corte y la vida diaria de sus gentes. El museo indica que la ropa de los hombres los identifica como armenios.","A la luz de una gran vela, hombres y mujeres juegan a las cartas en torno a una mesa cubierta con un paño rojo. Hay cartas repartidas sobre la mesa y algunos estudian las que tienen en la mano. En el rincón izquierdo una anciana hila. El registro no dice de qué juego se trata."],"spots":[["Cartas en la mesa","Cartas sobre la mesa de paño rojo."],["La gran vela","Una sola vela ilumina a todo el grupo."],["La anciana que hila","Una anciana hila en el rincón izquierdo."],["Mujer con sus cartas","A la derecha, una mujer mira sus cartas."],["El hombre del abrigo de piel","Un hombre con abrigo ribeteado de piel; la ropa los señala como armenios."],["Inclinado sobre la mesa","Alguien se inclina sobre la mesa con cartas en la mano."]]},"algiers":{"title":"Tres hombres jugando a un juego de tablero (Argel)","artist":"Anónimo","date":"1851–1900","place":"Argelia (Argel)","game":"Juego de tablero (probablemente backgammon)","medium":"Copia a la albúmina","size":"14,0 × 10,0 cm","credit":"","p":["Una fotografía anónima con la inscripción manuscrita «Alger» (Argel) bajo la imagen. Con sillas y una mesita ante un fondo liso, probablemente se tomó en un estudio. Viajeros y coleccionistas compraban fotos así de gentes del norte de África.","Dos hombres se sientan frente a frente ante un tablero con borde, y el de la derecha alarga la mano hacia una pieza. Hay piezas redondas apiladas sobre el tablero, así que probablemente es backgammon (llamado allí tawla, entre otros nombres), aunque el registro dice solo «un juego de tablero». En la mesita de delante hay útiles de café."],"spots":[["Tablero y piezas","Un tablero con borde y piezas redondas apiladas."],["El que mira de pie","Un hombre con faja en la cintura mira la partida desde atrás."],["El anciano, a la izquierda","Un hombre mayor con turbante, pensativo."],["El hombre de la derecha","Con un paño blanco en la cabeza, se inclina sobre el tablero."],["Los útiles de café","Bandeja y tacitas sobre una mesita calada."],["La mano que mueve","La mano del jugador de la derecha, a punto de tomar una pieza."]]},"circo":{"title":"Juego del Circo","artist":"Manuel Manilla (?)","date":"Sin fecha","place":"México","game":"Juego de apuestas con dos dados","medium":"Grabado en relieve o fotograbado sobre papel avitelado tostado","size":"26,2 × 35,0 cm","credit":"","p":["Una hoja de juego atribuida, con interrogación, al grabador mexicano Manuel Manilla. Abajo a la derecha figura quien la vendía, la Estampería «El Teatro», con su dirección. Hojas baratas como esta se vendían por la calle y, al parecer, se jugaban tal cual.","En el centro hay una carpa de circo, rodeada de jinetes acróbatas, una torre humana, un forzudo y otros, cada uno con un número del 2 al 12. La «Esplicacion» de arriba a la izquierda dice que pueden jugar todos, también niños: se tiran dos dados y se pone la apuesta en la casilla que sale, o se toma lo que ya hay en ella. Quien saca el doce se lo lleva todo."],"spots":[["La carpa","El título «JUEGO DEL CIRCO» y la carpa, que es la casilla 12."],["Las reglas","Las reglas, encabezadas por «ESPLICACION»."],["El jinete acróbata","Una bailarina sobre un caballo al galope: casilla 6."],["La torre humana","Un hombre de pie sobre los hombros de otro: casilla 4."],["El forzudo","Un hombre que alza un peso con forma de cañón: casilla 8."],["El nombre de la estampería","«De venta, Estampería “El Teatro”» y la dirección."]]},"loteria":{"title":"Juego de lotería","artist":"José Guadalupe Posada","date":"1880–1913","place":"México","game":"Lotería","medium":"Grabado en relieve o fotograbado sobre papel avitelado tostado","size":"30,0 × 40,0 cm","credit":"","p":["El grabador mexicano Posada dibujó muchísimas imágenes para el editor capitalino Antonio Vanegas Arroyo, cuyas hojas baratas llevaban noticias, canciones y juegos. Esta lleva el título «JUEGO DE LOTERIA» y el nombre de Vanegas Arroyo.","Llenan la hoja treinta y ocho pequeñas figuras con su nombre: la estrella, la luna, el alacrán, el diablo, la calavera, el gallo, la imprenta y otras. En la lotería, parecida al bingo, quien «canta» saca cartas y nombra las figuras, y los jugadores las marcan en su tabla con frijoles u otra cosa. Probablemente la hoja se recortaba en cartas."],"spots":[["Título y editor","«JUEGO DE LOTERIA» y el nombre de la casa de Vanegas Arroyo."],["La estrella","«ESTRELLA», la primera figura arriba a la izquierda."],["La luna","«LUNA», un creciente con cara."],["La muerte","«MUERTE»: un esqueleto con guadaña que toca la flauta."],["El tlachiquero","«TLACHIQUERO»: un hombre que recoge aguamiel del maguey."],["La imprenta","«IMPRENTA»: obreros ante una prensa, donde se hacían hojas como esta."]]},"jeupol":{"title":"«Jeu polonais», o tablero de damas","artist":"Anónimo","date":"1833–1900","place":"Bélgica o Países Bajos","game":"Damas (tablero de 10 × 10)","medium":"Xilografía con texto tipográfico","size":"32,2 × 39,6 cm","credit":"","p":["Una hoja suelta titulada en francés y neerlandés, «JEU POLONAIS OF DAMSPEL». «Jeu polonais» (el juego polaco) era el nombre francés de las damas en tablero de 10 × 10. Arriba a la derecha va el número de serie del editor, «n. 106».","Como dice el registro del museo, hay 100 casillas, 50 blancas y 50 negras, con orlas decorativas a izquierda y derecha. No hay piezas impresas, así que probablemente era un tablero barato que se usaba tal cual, con frijoles o botones como fichas. El papel conserva los pliegues."],"spots":[["El título","Las palabras «JEU POLONAIS OF DAMSPEL»."],["El número de serie","El número del editor, «n. 106»."],["La orla izquierda","Una columna de motivos florales redondos."],["La orla derecha","El mismo dibujo al otro lado."],["Las cien casillas","El tablero de 10 × 10; las casillas oscuras van rayadas con líneas finas."],["El pliegue","Un pliegue en el papel; quizá se llevaba doblado."]]},"dkaart":{"title":"Dominó y naipes para recortar","artist":"Anónimo (Brepols)","date":"1800–1833","place":"Bélgica (Turnhout)","game":"Dominó y naipes","medium":"Xilografía coloreada en azul, rojo y amarillo; texto tipográfico","size":"34,3 × 41,9 cm","credit":"","p":["Según el registro del museo, la hoja imprime 32 naipes y 28 fichas de dominó para recortar. Es el número 114 del catálogo del editor Brepols, con el revendedor «D. Pouwels, Bergen-op-Zoom» al pie. El título va en neerlandés y francés.","A la izquierda, las 28 fichas del blanco doble al seis doble se apilan en triángulo. A la derecha hay 32 naipes, del siete al diez más figuras y ases de cada palo: una baraja para juegos como el piquet. Como nadie la recortó, la vemos tal como salió de la prensa."],"spots":[["El título","Las palabras «DOMINO EN KAARTSPEL»."],["Blanco doble","La cima del triángulo: la ficha sin puntos."],["Seis doble","La ficha mayor, al final de la fila inferior."],["As de picas","La segunda carta de la columna izquierda."],["Una figura","Un rey coloreado en rojo, azul y amarillo."],["El revendedor","«D. POUWELS, Bergen-op-Zoom» abajo."]]},"apen":{"title":"Dos monos jugando al chaquete","artist":"Quirin Boel, según David Teniers","date":"1635–1690","place":"Flandes","game":"Chaquete (pariente del backgammon)","medium":"Aguafuerte","size":"11,0 × 14,5 cm","credit":"","p":["Una de una serie, portada y seis láminas, en la que monos imitan ocupaciones humanas. Abajo a la izquierda dice «D. Teniers lo inventó y publicó, con privilegio»: Quirin Boel grabó el diseño del pintor flamenco Teniers.","Como describe el registro del museo, dos monos se sientan en el suelo con un tablero de chaquete entre ellos. El de la izquierda bebe vino de una copa; el de la derecha, con un sombrero con pluma de gallo, alarga la mano hacia una pieza. Probablemente se burla de quienes se entregan a la bebida y al juego."],"spots":[["El tablero","Un tablero plegable en el suelo, con sus puntas y fichas."],["El mono de la izquierda","Un mono con chaqueta, sentado ante el tablero."],["La copa","La copa que alza el mono de la izquierda."],["El sombrero con pluma","Una pluma de gallo en el sombrero del de la derecha."],["La jarra","Una jarra a los pies del mono de la izquierda."],["La inscripción","«D Teniers in et excud cum privilegio»."]]},"dstereo":{"title":"Hombres jugando al dominó en una mesa (estereografía)","artist":"Anónimo","date":"1850–1880","place":"Desconocido (inscripción en neerlandés)","game":"Dominó","medium":"Copia a la albúmina (estereografía)","size":"8,5 × 17,0 cm","credit":"","p":["Una estereografía: dos fotografías casi idénticas una junto a otra. Vistas con un estereoscopio, se funden en una sola escena con profundidad. En el borde izquierdo se lee, escrito a mano, «Het dominospel» (el juego del dominó).","Han sacado una mesa al sol ante un edificio, y unos hombres en mangas de camisa sostienen sus fichas. Dos miran la partida de pie; el de la derecha lleva gorra blanca. Como todos debían quedarse quietos, la escena probablemente se preparó para la cámara."],"spots":[["Fichas en la mesa","Fichas de dominó boca abajo en las manos."],["El de la gorra blanca","Sentado a la derecha, con sus fichas."],["El del pañuelo","De pie, mirando la partida desde arriba."],["El de la izquierda","Un joven apoyado en el codo, con sus fichas."],["La inscripción","«Het dominospel.» escrito en el borde izquierdo."],["La segunda imagen","La foto de la derecha, tomada desde un punto algo desplazado: juntas se ven en relieve."]]},"gojo":{"title":"Dos mujeres jugando al go","artist":"Anónimo","date":"1870–1891","place":"Japón","game":"Probablemente go","medium":"Copia a la albúmina coloreada a mano","size":"9,0 × 13,5 cm","credit":"","p":["Una fotografía en blanco y negro coloreada a mano con pincel. Fotos así se hacían en estudios de Yokohama y otros lugares como recuerdo para extranjeros. Esta estaba pegada en un álbum de fotografías de un viaje a Manila.","Ante un adorno de tokonoma y un biombo, dos mujeres se sientan a ambos lados de un tablero con patas, y la de la izquierda coloca una piedra. Hay piedras blancas y negras en el tablero, así que probablemente es go, aunque el registro del museo dice «un juego de tablero». En la bandeja de delante hay dulces y cuencos."],"spots":[["Tablero y piedras","Un tablero grueso con patas y piedras blancas y negras."],["La mano que juega","La mujer de la izquierda coloca una piedra."],["La mujer de la izquierda","Se vuelve hacia nosotros; lleva el obi con un gran lazo."],["La mujer de la derecha","Con kimono a rayas, la mano junto al tablero."],["Bandeja y cuencos","Dulces y tazas delante."],["Las flores","Un jarrón con flores sobre un pie, al fondo."]]},"meade":{"title":"Dos hombres jugando al ajedrez","artist":"Charles Richard Meade y Henry William Mathew Meade","date":"1852","place":"Estados Unidos","game":"Ajedrez","medium":"Daguerrotipo","size":"6,9 × 8,3 cm","credit":"","p":["Un daguerrotipo del estudio de los hermanos Meade, fotógrafos nacidos en Inglaterra que trabajaron en Estados Unidos. El daguerrotipo forma la imagen directamente en una lámina de cobre plateada, así que cada uno es único e irrepetible; este va en un estuche de cuero tras un marco dorado.","Dos jóvenes están ante un tablero sobre un pie pequeño; el de la izquierda tiene los dedos sobre una pieza. El de la derecha, con la mano en el pecho, estudia el tablero. Como debían quedarse quietos mucho tiempo, la jugada probablemente es posada."],"spots":[["El tablero","El tablero y las piezas blancas sobre un pie cubierto con tela floreada."],["El de la izquierda","Con los dedos sobre una pieza."],["El de la derecha","Mira el tablero desde arriba."],["La mano en el pecho","La mano pensativa del de la derecha."],["La tela","Un pie pequeño cubierto de tela floreada."],["El marco dorado","El marco y el estuche que protegen la placa."]]},"weiqidai":{"title":"Paisaje con inmortales taoístas jugando al weiqi","artist":"Atribuido a Dai Jin","date":"Dinastía Ming, siglos XV–XVI","place":"China","game":"Weiqi (go)","medium":"Rollo colgante; tinta y colores sobre seda","size":"175,2 × 106,7 cm","credit":"","p":["Un gran rollo colgante atribuido al pintor Ming Dai Jin (h. 1388–1462). Natural de Zhejiang y conocido por sus vigorosos paisajes, más tarde se le tuvo por fundador de la escuela Zhe. Bajo acantilados altísimos y un gran árbol, las figuras son pequeñas.","En el suelo, a la sombra, dos inmortales se sientan ante un tablero de weiqi cuadriculado, con un plato de fruta y una jarra al lado. La figura agachada a la izquierda recuerda al leñador que miró jugar a los inmortales en la montaña hasta que se le pudrió el mango del hacha (la leyenda de Lanke), aunque el título del museo solo habla de inmortales jugando al weiqi."],"spots":[["El tablero","Un tablero con borde y una fina cuadrícula."],["El inmortal barbado","Un inmortal de larga barba, sentado con calma."],["El inmortal del gorro azul","Inclinado sobre el tablero; junto a su rodilla, un cuenco de piedras."],["La figura agachada","Mira el tablero desde la izquierda; quizá el leñador de la leyenda."],["Fruta y jarra","Un plato y una jarra al otro lado del tablero."],["Firma y sellos","Una firma y dos sellos rojos arriba a la derecha."]]},"reise":{"title":"El viaje alrededor del mundo, por mar y por tierra","artist":"Anónimo","date":"Siglo XIX","place":"Probablemente tierras de habla alemana","game":"Juego de carrera con un dado, con apuestas","medium":"Litografía","size":"42,5 × 33,7 cm","credit":"","p":["Una hoja de juego titulada en alemán «El viaje alrededor del mundo, por agua y por tierra: un nuevo y entretenido juego de dados». Un tablero redondo tiene casillas del 1 al 41, con dibujos de un globo, veleros, un vapor, una locomotora, gentes de varias naciones y más. Lleva el número «No. 107» abajo a la derecha.","Debajo van las reglas en alemán, inglés, neerlandés y francés. Cada jugador paga primero 15 marcos a la «bolsa del viaje» común; luego tira un dado por turno y avanza su ficha. Caer en una imagen grande gana 2 marcos, un número sin imagen cuesta 2 de multa, y quien llega al 41 se lleva todo lo demás."],"spots":[["41: la diligencia","La meta del centro: una diligencia con viajeros y cochero."],["1: el inglés","La casilla de salida, «Engländer» con chistera."],["El globo","Una casilla con un globo en el cielo."],["El velero","Un barco a toda vela."],["La locomotora","Una locomotora de vapor echando humo."],["Las reglas","Las reglas, impresas en cuatro lenguas."]]},"huchten":{"title":"Los dados por la vida o la muerte","artist":"Jan van Huchtenburg","date":"1680–1720","place":"Países Bajos","game":"Dados","medium":"Óleo sobre lienzo","size":"67,5 × 76,0 cm","credit":"","p":["Obra del pintor holandés Jan van Huchtenburg (1647–1733), conocido por sus batallas, firmada abajo a la izquierda. El título del museo es «El juego de dados por la vida». Fuera de una fortaleza, dos presos tiran los dados sobre un tambor, rodeados de oficiales y soldados.","Al fondo a la derecha se alza una horca, y desde la muralla de la izquierda miran otros soldados. Probablemente muestra a soldados condenados que echan a suertes con dados quién será ejecutado. Un preso señala el tambor; el otro, de rodillas, mira la tirada."],"spots":[["Tambor y dados","Un tambor hace de mesa para tirar los dados."],["El preso que señala","De pie, señala el tambor."],["El preso arrodillado","Con camisa blanca, inclinado sobre el tambor."],["El oficial a caballo","Con sombrero, mira desde su montura."],["La horca","La horca, arriba a la derecha."],["Soldados en la muralla","Soldados que miran desde la muralla."]]},"vertu":{"title":"El juego de la virtud (Spel der Deugd)","artist":"Jan Gerritsz. Visser (ideado por J. Voorman)","date":"1798","place":"Países Bajos","game":"Juego de apuestas con dos dados","medium":"Grabado a buril, aguafuerte y tipografía","size":"56,9 × 38,0 cm","credit":"","p":["Una gran hoja de juego titulada en neerlandés y francés «El juego de la virtud». En un templo de columnas se sienta la Virtud en el centro, con la Prosperidad de pie a la izquierda y la Pobreza a la derecha. En las columnas cuelgan medallones de virtudes como la Sinceridad, la Gratitud o el Amor, y en los pedestales hay vicios como la Avaricia, el Orgullo y la Pereza.","Según las reglas de abajo, se juega con dos dados o sacando suertes. Con dados, los jugadores apuestan 63 en total y tiran por turno siguiendo el curso del sol. Cada tirada nombra una virtud o un vicio: el doble seis, la Virtud, se lleva el bote, y el doble uno, el Vicio, paga ocho. Bajo cada imagen, «T» es lo que se cobra y «B» lo que se paga."],"spots":[["El título","«SPEL DER DEUGD» en el frontón."],["La Virtud","La Virtud (LA VERTU) en el trono central; el doble seis se lleva el bote."],["La Prosperidad","La Prosperidad con su cuerno de la abundancia."],["El Vicio","El doble uno, el Vicio (LE VICE): un niño que alza una copa."],["La Avaricia","La Avaricia (L’AVARICE) en el pedestal; «B» y los dados dicen lo que se paga."],["Las reglas","Las reglas, impresas apretadas abajo."]]},"charros":{"title":"Los charros contrabandistas. Juego de dados","artist":"José Guadalupe Posada","date":"Sin fecha","place":"México","game":"Juego de carrera con tres dados","medium":"Litografía","size":"29,9 × 40,4 cm","credit":"","p":["Un juego de recorrido con dibujos de Posada, titulado «LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS». Abajo va el pie de la Imprenta de A. Vanegas Arroyo, México, y Posada firmó abajo a la derecha. En las esquinas galopan charros con sombrero.","Casillas redondas orladas de soga serpentean por todo el tablero, con animales, personas, un tren y más. La «Explicación» de arriba a la derecha dice que se juega con tres dados. Tres unos en la primera tirada ganan; caer en la calavera pierde; en el venado se cobra del fondo, en los ladrones se paga, y en el león uno se queda quieto hasta que otro lo saque."],"spots":[["El título","«LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS»."],["La explicación","Las reglas, bajo «EXPLICACION»."],["Los jugadores","Gente en torno a una mesa, jugando a un tablero, abajo a la izquierda."],["Los dados","Tres dados dibujados en medio del tablero."],["El charro a caballo","Un charro que galopa y voltea la reata."],["La imprenta","«IMPRENTA DE A. VANEGAS ARROYO, MÉXICO»."]]},"snuffwq":{"title":"Tabaquera con figuras jugando al weiqi","artist":"China","date":"Dinastía Qing, marca y época del reinado Daoguang (1820–50)","place":"China","game":"Weiqi (go)","medium":"Porcelana pintada con esmaltes sobre cubierta","size":"Alto 5,7 cm","credit":"","p":["Un frasquito para llevar rapé en la China Qing. El registro del museo indica una marca del reinado Daoguang y lo fecha en 1820–50. En su cuerpo de porcelana blanca, de unos seis centímetros, hay un paisaje montañoso y figuras pintadas con esmaltes.","Junto a una roca como una cueva, dos ancianos se sientan ante un tablero de weiqi sobre un pie azul; el de la izquierda va a poner una piedra. Detrás mira un niño con un bastón. El tema probablemente evoca la leyenda del leñador que miró jugar a los inmortales."],"spots":[["El tablero","Un tablero sobre un pie azul, con una fina cuadrícula."],["El anciano barbado","De túnica morada, alarga la mano hacia el tablero."],["El anciano de enfrente","Sentado a la derecha, alza la mano mientras mira."],["El niño del bastón","Mira desde atrás."],["La gruta","Una roca como una cueva tras los jugadores."],["El tapón","Un tapón verde."]]},"ostade":{"title":"Jugadores de chaquete en una taberna","artist":"Adriaen van Ostade","date":"1653","place":"Países Bajos (Haarlem)","game":"Chaquete (pariente del backgammon)","medium":"Aguafuerte","size":"8,5 × 7,4 cm","credit":"","p":["Un aguafuerte del tamaño de una mano del pintor de Haarlem Ostade, conocido por sus escenas campesinas, firmado «A. ostade» abajo. En una taberna oscura, la luz de una ventana emplomada cae sobre la gente.","En la mesa de la izquierda dos hombres se enfrentan ante un tablero de chaquete y un tercero mira desde atrás. A la derecha un hombre se recuesta contra la pared con un vaso en la mano. Una gran jarra yace en el suelo; parece una tarde ociosa en la taberna."],"spots":[["El tablero","Un tablero de chaquete sobre la mesa."],["El jugador de la izquierda","Un hombre con sombrero ante el tablero."],["El jugador de la derecha","Inclinado sobre el tablero."],["El que mira","Un hombre de pie detrás, observando."],["El que descansa","Sentado junto a la pared, vaso en mano."],["La ventana emplomada","Una ventana de rombos por donde entra la luz."]]},"lenain":{"title":"Los jugadores de dados","artist":"Seguidor de Mathieu Le Nain","date":"1630–1680","place":"Francia","game":"Dados","medium":"Óleo sobre lienzo","size":"92,8 × 119,7 cm","credit":"","p":["Obra de un seguidor de Mathieu, el menor de los hermanos franceses Le Nain. El museo señala que un boceto de una composición parecida, de Gabriel de Saint-Aubin, está en la Bibliothèque nationale de París.","Tres hombres rodean una mesita redonda al aire libre y tiran los dados; otros dos miran, y el de la izquierda abraza una botella. A la derecha hay dos lebreles esbeltos, y al fondo se abre un amplio paisaje. Las cositas blancas de la mesa son los dados."],"spots":[["Dados en la mesa","Dados sobre la mesa redonda."],["El del sombrero claro","Sentado, alarga la mano para ver la tirada."],["El de negro","Un joven de pie, con la mano en la cadera."],["El muchacho de atrás","Mira la partida detrás de la mesa."],["El de la botella","A la izquierda, nos sonríe."],["Los dos lebreles","Perros esbeltos a la derecha."]]},"tunisie":{"title":"Partida de cartas ante un café árabe (sección tunecina, Exposición de Amberes)","artist":"Anónimo (impreso por Ch. Bernhoeft)","date":"1894","place":"Bélgica (Amberes)","game":"Naipes","medium":"Fototipia","size":"15,4 × 21,6 cm","credit":"","p":["Una de una serie de 49 láminas de la Exposición Universal de Amberes de 1894, con «EXPOSITION UNIVERSELLE D’ANVERS 1894» arriba y «Túnez: partida de cartas ante un café árabe» abajo. La imprimió Bernhoeft, fotógrafo de la corte en Luxemburgo.","Se tomó en una plaza con cúpulas y una torre construida para la sección tunecina de la exposición. Hombres con ropa tunecina juegan a las cartas en mesitas de azulejos; uno fuma en narguile y hay una bandeja de tazas. A la derecha se sientan visitantes de traje: probablemente era una exhibición de la vida de un país lejano."],"spots":[["La mesa de cartas","Hombres con naipes en torno a una mesita de azulejos."],["El narguile","El tubo del narguile del hombre de la izquierda."],["Visitantes de traje","Hombres de traje sentados a la derecha, probablemente público de la feria."],["La bandeja de tazas","Tazas pequeñas bajo la mesa."],["Cúpulas y torre","Edificios de estilo tunecino levantados para la feria."],["El rótulo","«TUNISIE» y «PARTIE DE CARTES DEVANT UN CAFÉ ARABE»."]]},"laghouat":{"title":"Caídes de los alrededores de Laghouat","artist":"Anónimo","date":"1880–1890","place":"Argelia (cerca de Laghouat)","game":"Probablemente dominó","medium":"Copia a la albúmina","size":"20,9 × 27,0 cm","credit":"","p":["Una fotografía titulada «Tipos argelinos: caídes de los alrededores de Laghouat», pegada en un álbum y con el número «239» impreso. Caíd era el título de un jefe local en la Argelia bajo dominio francés.","Hombres con túnicas blancas, sentados en una estera ante un muro de adobe, colocan fichas alargadas sobre una mesita baja. Por cómo están dispuestas, probablemente es dominó, aunque el registro del museo dice solo «un juego». Delante hay una bandeja de té y las babuchas que se han quitado."],"spots":[["Fichas en la mesita","Fichas alargadas en fila sobre la mesa."],["La bandeja de té","Vasos y tetera en una bandeja delante."],["Las babuchas","Calzado dejado junto a la estera."],["La figura de pie","Alguien de pie junto al muro, mirando."],["El muro de adobe","El áspero muro de tierra al fondo."],["La estera","La estera tejida donde se sientan."]]},"hangong":{"title":"Damas de palacio (Mañana de primavera en el palacio Han), detalle","artist":"Copia según Qiu Ying","date":"Dinastía Qing (1644–1911)","place":"China","game":"Weiqi (go)","medium":"Rollo horizontal; tinta y color sobre seda","size":"36,2 × 454,4 cm (rollo entero)","credit":"","p":["Un detalle de un rollo horizontal de más de cuatro metros y medio, copia de época Qing de una composición del pintor Ming Qiu Ying (1494–1552). Por un palacio en un día de primavera, damas, muchachas y criadas se columpian, juegan, admiran peonías, hacen música, tocan el qin y dan de comer a un loro y a los peces.","En esta escena, dos mujeres se enfrentan ante un tablero de weiqi tras una balaustrada, mientras otras se inclinan para mirar. Delante hay una roca de letrado en una pila con forma de loto, y unas criadas llevan instrumentos y bultos. Como señala el museo, el rollo idealiza la vida de las mujeres en los aposentos interiores del palacio."],"spots":[["El tablero","Un tablero de weiqi sobre una mesa tras la balaustrada."],["La que coloca una piedra","Una mujer de morado claro que alarga la mano al tablero."],["Las que miran","Mujeres inclinadas para ver la posición."],["La dama del abanico","Una mujer con un abanico redondo entre las columnas."],["La roca de letrado","Una roca azul en una pila con forma de loto."],["La criada con el instrumento","Una criada que lleva lo que probablemente es una pipa."]]},"homerbg":{"title":"Backgammon","artist":"Winslow Homer","date":"h. 1877","place":"Estados Unidos","game":"Backgammon","medium":"Grabado en madera a contrafibra","size":"","credit":"","p":["Un grabado en madera según un dibujo del pintor estadounidense Winslow Homer (1836–1910), que de joven hizo muchas ilustraciones para estampas así. Abajo se lee «396.—BACKGAMMON.—WINSLOW HOMER.», así que probablemente formaba parte de una serie numerada en un libro o revista.","Dos mujeres sentadas frente a frente en un sofá ornamentado juegan al backgammon sobre un tablero apoyado en sus regazos. Sobre el tablero hay un objeto redondo y blanco, aunque no está claro qué es. Los pliegues de las faldas largas y los brazos en voluta del sofá están tallados en líneas finas."],"spots":[["El tablero","El tablero apoyado en los regazos de las dos."],["La mujer de la izquierda","Con el pelo recogido, alarga la mano al tablero."],["La mujer de la derecha","Se inclina para estudiar el tablero."],["El brazo del sofá","Un brazo en forma de voluta."],["Las faldas","Faldas largas con pliegues en líneas finas."],["El pie","«396.—BACKGAMMON.—WINSLOW HOMER.» abajo."]]},"chessst":{"title":"Hombre y mujer jugando al ajedrez (estereografía)","artist":"Anónimo","date":"1852–1858","place":"Desconocido","game":"Ajedrez","medium":"Estereografía coloreada","size":"8,3 × 16,5 cm","credit":"","p":["Un par de fotografías montadas como estereografía, conocida en inglés como «The Chess Players». Vistas con estereoscopio, el tablero y las piezas parecen salir en relieve. Se ha añadido color sobre la imagen en blanco y negro, en la cortina roja y el vestido amarillo.","La mujer de amarillo tiene la mano sobre una pieza, mientras el hombre de enfrente, visto de espaldas, estudia el tablero. Hay piezas rojas y blancas en plena partida, pero la escena probablemente se preparó en un estudio. Estas estereografías de escenas domésticas se vendían mucho a mediados del siglo XIX."],"spots":[["Tablero y piezas","Piezas rojas y blancas en el tablero escaqueado."],["La mano que mueve","La mano de la mujer sobre una pieza."],["La mujer","Con vestido amarillo y cuello blanco, mira el tablero."],["El hombre","Sentado de espaldas a nosotros."],["La cortina roja","La cortina coloreada del fondo."],["La segunda imagen","La vista derecha; con estereoscopio el par gana profundidad."]]},"corrida":{"title":"Corrida de toros: juego de dados","artist":"José Guadalupe Posada","date":"1898","place":"México","game":"Juego de carrera con dos dados, con apuestas","medium":"Fotograbado en relieve sobre papel avitelado","size":"40,4 × 30,0 cm","credit":"","p":["Un juego de recorrido con dibujos de Posada, titulado «CORRIDA DE TOROS». Las casillas van en espiral y muestran en orden las suertes y momentos de la lidia, desde la casilla 1, por fuera, hacia el centro. En medio hay una plaza de toros, y abajo el nombre de la imprenta de Antonio Vanegas Arroyo.","Según la «Explicación» del pie, juegan dos o más personas poniendo cada una su apuesta y tirando dos dados. El 5, «salto de garrocha», va al 10; el 12, «cogida del picador», paga y se queda sin jugar; el 28, «pase de pecho», vuelve a empezar. Quien llega al 32, «arrastre del toro», se lleva todas las apuestas."],"spots":[["El título","Las palabras «CORRIDA DE TOROS»."],["La plaza","La plaza de toros en el centro de la espiral."],["La casilla 1","La salida, a la entrada de la espiral."],["La cabeza del toro","Una cabeza de toro astada, arriba a la derecha."],["El torero","El retrato de un torero, abajo a la izquierda."],["La explicación","La «EXPLICACION» impresa al pie."]]},"ambrocards":{"title":"Tres hombres jugando a las cartas","artist":"Autor desconocido (estadounidense)","date":"1865","place":"Estados Unidos","game":"Naipes","medium":"Ambrotipo","size":"14,0 × 11,0 cm","credit":"","p":["Un ambrotipo es un negativo fino sobre vidrio con un fondo negro detrás, de modo que se ve como positivo. Más barato que el daguerrotipo, se usó mucho en Estados Unidos en las décadas de 1850 y 1860. Este va tras un marco dorado en un estuche forrado de terciopelo rojo.","Ante un fondo liso, tres hombres rodean una mesita con sus cartas en la mano. El de la izquierda lleva bombín y el de la derecha gorra, ambos con un puro en la boca; el del centro, de chaqueta oscura, nos mira. Probablemente posaron como en plena partida para la cámara."],"spots":[["Las manos","Manos con cartas sobre la mesa."],["El del bombín","A la izquierda, con puro."],["El del centro","De chaqueta oscura, nos mira."],["El de la gorra","A la derecha, con puro."],["El marco dorado","El marco dorado estampado que rodea la imagen."],["El estuche","El estuche forrado de terciopelo rojo."]]},"morphy":{"title":"Paul Morphy, el campeón de ajedrez","artist":"Winslow Homer","date":"1859","place":"Estados Unidos","game":"Ajedrez","medium":"Grabado en madera a contrafibra","size":"","credit":"","p":["Un retrato grabado en madera con el pie «PAUL MORPHY, THE CHESS CHAMPION», según un dibujo de Winslow Homer (1836–1910), entonces un joven ilustrador. Morphy (1837–1884), de Nueva Orleans, recorrió Europa en 1858–59 venciendo a un maestro tras otro y volvió a casa famoso.","El joven Morphy, sentado, apoya la mano izquierda en el borde de un tablero, junto a un rey, una torre, peones y otras piezas. Hecho en 1859, cuando regresó convertido en celebridad, probablemente se imprimió como ilustración en un periódico o revista."],"spots":[["Las piezas","Un rey, una torre, peones y otras en el tablero."],["La mano en el tablero","Su mano izquierda en el borde del tablero."],["El rostro de Morphy","El campeón, recién pasados los veinte."],["La pajarita","Un cuello bien arreglado."],["La mano en la rodilla","Su mano derecha sobre la rodilla."],["El título","«PAUL MORPHY, THE CHESS CHAMPION» abajo."]]},"dutton":{"title":"La familia Dutton en el salón de Sherborne Park, Gloucestershire","artist":"Johann Zoffany","date":"h. 1772","place":"Inglaterra","game":"Naipes","medium":"Óleo sobre lienzo","size":"101,5 × 127,0 cm","credit":"","p":["Obra de Johann Zoffany (1733–1810), pintor nacido en Alemania que hizo carrera en Inglaterra. El «conversation piece», que retrata a una familia de manera informal, nació en la Inglaterra del siglo XVIII y fue muy popular. La escena es el salón de Sherborne Park, en Gloucestershire.","Según el museo, padre e hija y madre e hijo calculan la siguiente jugada en una partida de naipes. La familia acababa de perder a un ser querido, así que los padres visten luto riguroso negro y los hijos medio luto en malva, blanco y gris."],"spots":[["La mesa de juego","Una mesa con tapete verde y naipes."],["El padre","De negro, con sus cartas."],["La hija","De blanco, mirando su mano."],["El hijo","De gris, con sus cartas."],["La madre","Con luto negro."],["La chimenea","Una chimenea de mármol encendida."]]},"whist":{"title":"Los académicos de Navidad: una partida combinada de whist","artist":"James Bretherton (probablemente según H. W. Bunbury)","date":"1773","place":"Inglaterra","game":"Whist (naipes)","medium":"Aguafuerte","size":"26,5 × 39,6 cm","credit":"","p":["Según el museo, una sátira de los académicos de Cambridge. Abajo a la izquierda parece leerse «H. W. Bunbury del. 1772» y a la derecha «J. Bretherton f.»; se publicó en 1773 en una tienda de New Bond Street, Londres. En la pared cuelgan birretes académicos.","Cuatro caballeros juegan al whist mientras se hacen muecas. El whist se juega en dos parejas, así que la «partida combinada» del título es probablemente un juego de palabras. Detrás, uno hace un gesto burlón con los dedos sobre la cabeza de otro. Cerca hay dos criados y dos perros."],"spots":[["Naipes en la mesa","Cartas jugadas sobre la mesa."],["El académico de peluca","Un sabio con gran peluca, la mano junto al pecho."],["El gesto de los dedos","Un hombre detrás alza los dedos sobre la cabeza de otro."],["La criada","Una sirvienta con sombrero y bandeja."],["Los birretes","Birretes universitarios colgados en la pared."],["El perro de la derecha","Un perrito que ladra abajo a la derecha."]]},"hey":{"title":"Tres hombres jugando al ajedrez","artist":"Paul Hey","date":"1877–1952","place":"Alemania","game":"Ajedrez","medium":"Grabado (probablemente aguafuerte)","size":"19,3 × 26,0 cm","credit":"","p":["Un grabado del pintor e ilustrador alemán Paul Hey (1867–1952). Tres hombres mayores se inclinan sobre un mismo tablero; finas líneas superpuestas dibujan sus arrugas y barbas blancas.","Como anota el registro del museo, el de la izquierda apoya la mano en el mentón y el de la derecha sostiene un puro mientras alarga la mano sobre las piezas. A la izquierda de la mesa hay dos tazas de café, un vaso y una caja de cerillas. Probablemente una partida en un café."],"spots":[["El tablero","Tablero y piezas sobre la mesa."],["El de la mano en el mentón","De barba blanca, pensativo."],["El del centro","Inclinado, alarga la mano hacia una pieza."],["El de la derecha","Mira desde atrás."],["La mano con el puro","Un puro entre los dedos."],["Café y cerillas","Dos tazas, un vaso y una caja de cerillas a la izquierda."]]},"artful":{"title":"La carta astuta, o una de más para la abuela. ¡Corazones son triunfo!","artist":"Anónimo","date":"1852–1863","place":"Probablemente Gran Bretaña","game":"Naipes","medium":"Estereografía coloreada","size":"8,4 × 17,4 cm","credit":"","p":["El título inglés es «The artful card, or, one too many for granny. Hearts are trumps!». Una escena cómica en la que se engaña a la abuela con una carta astuta, convertida en un par de fotografías estereoscópicas. Por el título en inglés, probablemente se hizo en Gran Bretaña.","En una mesa redonda la abuela y una niña juegan a las cartas, mientras la joven de verde, con su mano de naipes, recibe el abrazo de un joven por detrás. «Corazones son triunfo» es probablemente un juego de palabras entre el palo y el amor. La habitación con rueca y alacena es sin duda un decorado de estudio."],"spots":[["Las cartas de la joven","Los naipes que sostiene la joven de verde."],["El joven","Con la mano en el hombro de ella."],["La abuela","Mujer mayor con pañuelo, mirando sus cartas."],["La niña","Sonríe mientras juega una carta."],["La mesa","Mesa redonda con naipes y cosillas."],["La alacena","Un armario acristalado con loza."]]},"cezcards":{"title":"Estudio para Los jugadores de cartas","artist":"Paul Cézanne","date":"1890–92","place":"Francia","game":"Naipes","medium":"Acuarela con grafito sobre papel avitelado beige","size":"36,2 × 48,5 cm","credit":"","p":["En la década de 1890, en Aix, en el sur de Francia, Cézanne pintó varios cuadros de hombres jugando a las cartas. Esta es una acuarela preparatoria para esa serie: un hombre con sombrero y bigote, sentado a la mesa, mira sus cartas.","Sobre líneas de grafito, finas aguadas azules y grises recogen los pliegues de la chaqueta y el peso del cuerpo. El lado derecho y el fondo de la mesa quedan sin terminar; solo hay color alrededor de la figura. Se dice que sus modelos eran trabajadores del lugar."],"spots":[["El rostro","Con los ojos bajos bajo el sombrero, mira sus cartas."],["Las cartas","Cartas sostenidas con ambas manos."],["La mesa","Una mesa dibujada solo a lápiz."],["La silla","El respaldo de la silla, a la izquierda."],["La chaqueta","Pliegues construidos en azul y gris."],["Lo inacabado","Junto a las patas de la mesa solo quedan las líneas."]]},"vuillardck":{"title":"La partida de damas, de Paisajes e interiores","artist":"Édouard Vuillard","date":"1899","place":"Francia","game":"Damas","medium":"Litografía en color sobre papel de China marfil grisáceo","size":"36,9 × 28,5 cm","credit":"","p":["La primera lámina de Paisajes e interiores, álbum de litografías en color del pintor francés Vuillard, editado por el marchante Ambroise Vollard e impreso por el litógrafo Auguste Clot.","En una habitación cargada de papel pintado, un hombre barbudo juega ante un tablero de damas mientras una mujer con vestido de cuadros, de pie, se lleva la mano al mentón y mira. Figuras, papel y sofá se funden en color plano y dibujo; solo los escaques blancos y negros del tablero destacan con nitidez."],"spots":[["El tablero","El tablero de damas blanco y negro."],["El hombre barbudo","Sentado ante el tablero."],["La mujer de pie","Con vestido de cuadros y la mano en el mentón."],["El papel pintado","Papel lleno de líneas en remolino."],["El cojín floreado","Tela estampada abajo a la izquierda."],["La lámpara","Una forma esbelta de lámpara junto a la pared."]]},"cruikchess":{"title":"Partida de ajedrez","artist":"George Cruikshank, según el capitán Frederick Marryat","date":"1814","place":"Inglaterra","game":"Ajedrez","medium":"Aguafuerte coloreado a mano","size":"23,8 × 34,5 cm","credit":"","p":["Una estampa del caricaturista inglés Cruikshank según un boceto de Marryat, oficial de marina y luego novelista, editada en Londres por Hannah Humphrey. Abajo va el título «GAME of CHESS».","Ante una mesa con velas, dos caballeros ancianos se enfrentan sobre el tablero. Detrás de cada uno hay un mirón: el de la izquierda se pone un dedo en los labios pidiendo silencio, y el de la derecha examina el tablero con unos impertinentes. Probablemente se burla de los mirones que no saben callar."],"spots":[["El tablero","El tablero con sus piezas blancas y negras."],["Las velas","Dos velas que iluminan el tablero."],["El que pide silencio","Un mirón con un dedo en los labios."],["El de los impertinentes","Un mirón que mira por sus impertinentes."],["El perro dormido","Un perro dormido bajo la mesa."],["El título","«GAME of CHESS» al pie."]]},"domino98":{"title":"Mujer y niña jugando al dominó en una mesa","artist":"Autor desconocido (estadounidense)","date":"h. 1898","place":"Estados Unidos","game":"Dominó","medium":"Copia a la albúmina adherida a vidrio","size":"40,8 × 51,1 cm","credit":"","p":["Una gran fotografía, probablemente de un estudio estadounidense, terminada pegándola a un vidrio. Una mujer vestida de blanco y una niña de pelo rizado se sientan a ambos lados de una mesita adornada con flores.","Sobre la mesa hay fichas de dominó y la mujer está colocando una. La niña, con la barbilla en la mano, mira. Las cortinas, el mueble recargado y los cuadros de la pared son probablemente un decorado de estudio."],"spots":[["Las fichas","Fichas blancas sobre la mesa."],["La niña","Con la barbilla en la mano, mira las fichas."],["La mujer","De blanco, coloca una ficha."],["Las flores","Un jarrón con flores en la mesa."],["El mueble","Un mueble recargado al fondo a la derecha."],["La inscripción","Letras blancas abajo a la derecha."]]},"langkat":{"title":"Albert Glaser jugando a las cartas con dos amigos en un barco, Langkat, Sumatra","artist":"Anónimo (H. Ernst & Co.)","date":"1895–1905","place":"Indonesia (Langkat, Sumatra)","game":"Naipes","medium":"Fotografía","size":"17,5 × 22,8 cm","credit":"","p":["Una fotografía tomada en Langkat, en el norte de Sumatra. Abajo a la derecha lleva el sello en seco del estudio «H. Ernst & Co. / Bindjey Langkat», y al dorso una nota manuscrita dice que el hombre del centro es Albert Glaser, hermano de una señora.","En la cubierta de un barco, bajo un toldo, tres hombres vestidos de blanco se sientan a una mesa con naipes en la mano. Sobre la mesa hay cartas y piezas pequeñas como monedas, y junto al hombre de la derecha una botella. La ropa blanca y el toldo hablan de la vida en un clima caluroso."],"spots":[["Sobre la mesa","Cartas repartidas y piezas como monedas."],["Glaser","El del centro abre sus cartas; la nota del dorso lo nombra."],["El de la izquierda","Visto medio de espaldas, con naipes."],["El de la derecha","Con bigote, naipes en mano."],["La botella","Una botella junto al de la derecha."],["El toldo","Adornos de hojas que cuelgan del toldo."]]},"chatur":{"title":"Una partida de chaturanga","artist":"Anónimo","date":"1805–1815","place":"India","game":"Chaturanga","medium":"Gouache y oro, pincel","size":"16,2 × 9,8 cm (imagen)","credit":"","p":["Una miniatura india. Según el registro del museo, dos mujeres juegan al chaturanga, un juego de tablero, mientras una criada sostiene un espantamoscas. El chaturanga es un antiguo juego indio, considerado el antepasado del ajedrez.","Bajo arcos blancos, sobre una alfombra roja, una mujer de azul oscuro y otra de naranja se enfrentan ante un tablero ajedrezado. La de naranja tiende la mano como si hablara. La imagen está enmarcada por un borde rojo oscuro con filetes negros y blancos."],"spots":[["El tablero","Un tablero ajedrezado sobre la alfombra roja."],["La mujer de azul","Adornada con oro, alarga la mano al tablero."],["La mujer de naranja","Frente a ella, con la mano tendida."],["La criada","De pie, detrás."],["El espantamoscas","Lo alza la criada."],["El marco rojo","Un borde rojo oscuro con filetes negros y blancos."]]},"shabbarat":{"title":"Noche en los aposentos de las mujeres","artist":"Anónimo","date":"1760–1770","place":"India","game":"Chaupar (pachisi)","medium":"Gouache y oro, pincel","size":"34,3 × 25,6 cm","credit":"","p":["Una miniatura india. Según el registro del museo, cuatro mujeres juegan a un juego de tablero en el amplio patio de un palacio, el juego llamado chaupar o pachisi. Se sientan en torno a un tablero de tela en forma de cruz.","La mujer de delante a la derecha sostiene tres dados alargados, lista para tirar. A su lado, recostada en un cojín, está la dama más importante. Es de noche, pero hay lámparas por toda la terraza y luces sin número en las murallas lejanas. El registro sugiere que se celebra la fiesta islámica de Shab-i-Barat."],"spots":[["El tablero en cruz","El tablero en forma de cruz extendido en el suelo."],["La de los dados","Delante, con los dados alargados."],["La dama del cojín","La de más alto rango."],["La criada","Se acerca con una bandeja."],["Una lámpara","Una vela bajo una campana de vidrio."],["El pabellón lejano","Un jardín con fuente, un pabellón y las luces de la ciudad."]]},"govase":{"title":"Jarrón ovoide con mujeres jugando al go","artist":"Anónimo (sello de «Tang Jintang»)","date":"1724","place":"China (Guangdong)","game":"Go (weiqi)","medium":"Porcelana con esmaltes sobre cubierta y dorado","size":"Altura 15,3 cm","credit":"","p":["Un jarrón chino de porcelana finísima pintado con esmaltes. Al dorso, una inscripción dice «cuadro de una partida de go, pintado el día de la Fiesta de las Flores del año jiachen, en una casa acogedora junto al río de las Perlas, en Lingnan», con el sello rojo «Tang Jintang». Perteneció a la colección de porcelana del coleccionista de La Haya Jean Theodore Royer.","Dos mujeres se enfrentan ante un tablero de go sobre una mesa; la de la izquierda sostiene un cuenco de piedras. A la derecha, dos mujeres y dos niños se inclinan para mirar. En el mueble de atrás hay antigüedades, entre ellas un jarrón con plumas de pavo real y coral."],"spots":[["El tablero","Un tablero de go en la mesa, con piedras blancas y negras."],["La jugadora de la izquierda","Con un cuenco de piedras, señalando."],["La jugadora de la derecha","Inclinada sobre el tablero."],["Las que miran","Mujeres que observan desde atrás."],["Plumas de pavo real y coral","En un jarrón sobre el mueble."],["El cuenco de piedras","En manos de la mujer de la izquierda."]]},"yokihi":{"title":"Un hombre juega al backgammon con una dama (el emperador Xuanzong y Yang Guifei)","artist":"Anónimo (surimono)","date":"1822","place":"Japón","game":"Ban-sugoroku (backgammon japonés)","medium":"Xilografía en color con pigmentos metálicos","size":"21,6 × 19,1 cm","credit":"","p":["Un surimono, estampa de lujo que une imagen y poesía, impresa en papel grueso con polvos metálicos y encargada por poetas como regalo para amigos. Esta lleva un poema y el nombre del poeta, Tachibana no Goen.","Según el registro del museo, el emperador Tang Xuanzong (685–762) juega al sugoroku con su consorte favorita Yang Guifei (719–756), un juego emparentado con el backgammon y el chaquete. Sobre un tablero en forma de caja, apoyado en un pie rojo, hay fichas blancas y negras."],"spots":[["El tablero","Un tablero de sugoroku en forma de caja sobre un pie rojo."],["Yang Guifei","Con flores en el pelo y la mano en el tablero."],["Xuanzong","Con la mano en la barbilla, mira el tablero."],["El poema","Un poema y el nombre del poeta arriba a la izquierda."],["El biombo","Un biombo pintado con montañas al fondo."],["Firma y sello","Una firma y un sello rojo abajo a la derecha."]]},"disderi":{"title":"Hombres con traje de marinero jugando a las cartas","artist":"Disdéri & Cie","date":"1850–1890","place":"Francia (París)","game":"Naipes","medium":"Copia a la albúmina (carte de visite)","size":"8,6 × 5,3 cm","credit":"","p":["Una fotografía de formato carte de visite de un álbum, con el nombre de Disdéri & Cie, bulevar de los Italianos 8, París, impreso al dorso. Disdéri fue el fotógrafo que popularizó la carte de visite, pequeños retratos impresos de muchos en muchos como tarjetas de visita.","Hombres vestidos a la antigua, con tricornio, casaca larga y medias blancas, juegan a las cartas en torno a una mesa con motivos. El registro del museo habla de traje de marinero, pero probablemente es vestuario de teatro o de mascarada. El del centro se levanta para mirar la mesa."],"spots":[["La mesa","Una mesa con orla de motivos; naipes y vasos encima."],["El que está de pie","Con tricornio, se inclina sobre la mesa."],["El de la izquierda","Sentado, con naipes."],["El de la derecha","Con tricornio y naipes en la mano."],["Zapatos con hebilla","Medias blancas y zapatos de hebilla."],["El marco dorado","La orla dorada del soporte."]]},"gans":{"title":"Juego de la oca (espiral de 74 casillas)","artist":"Jan Oortman (padre), según diseño de Daniel Willem Stoopendaal","date":"1763–1823","place":"Países Bajos","game":"Juego de la oca (carrera)","medium":"Xilografía coloreada en azul, rojo y verde","size":"40,8 × 46,8 cm","credit":"","p":["Un tablero de carrera en espiral impreso en los Países Bajos. Según el museo, las casillas van del 1 al 74 y algunas llevan imágenes. Jan Oortman talló la plancha según un diseño de Stoopendaal, cuyo nombre figura abajo a la derecha con «invenit».","La meta, el 74, es un templo junto al mar al atardecer, en el centro. Hay casillas con palabras como «LEER GELD» (precio del aprendizaje), «DWAALWEG» (camino errado) y «DOMHEID / WYSHEID» (necedad / sabiduría), y un esqueleto con guadaña, «EINDE» (el fin); probablemente era un juego moral sobre el camino de la vida."],"spots":[["74: el templo","La meta: un templo en la orilla al atardecer."],["1: la salida","La primera casilla, abajo a la izquierda."],["El precio","Una casilla «LEER GELD», probablemente donde se paga."],["El camino errado","Un sendero de bosque con «DWAALWEG»."],["El fin","Un esqueleto con guadaña: «EINDE»."],["Los dados","Una casilla con dos dados."]]},"merelle":{"title":"La merelle y la cometa","artist":"Claudine Stella, según Jacques Stella","date":"1657","place":"Francia (París)","game":"Merelle (molino o nueve hombres)","medium":"Grabado a buril","size":"11,7 × 14,1 cm","credit":"","p":["Lámina 17 de una serie de juegos infantiles grabada por Claudine Stella según diseños de su tío, el pintor Jacques Stella. Según el museo procede de un álbum de 51 grabados. Los que juegan son niños desnudos y rollizos, putti.","Delante a la izquierda juegan a la merelle (el molino) en un tablero rayado sobre un bloque de piedra. En el suelo de la derecha están las líneas del franc du carreau, un juego de lanzar monedas sobre baldosas, y más lejos un niño corre con una cometa. El verso de abajo dice que cada uno se esfuerza por jugar bien."],"spots":[["El tablero","Un tablero tallado en piedra, con fichas."],["La cometa","Una cometa en lo alto."],["El niño de la cometa","Corre con el hilo en la mano."],["Franc du carreau","Cuadrados y diagonales en el suelo."],["El niño que señala","Con algo en la mano, señala las líneas."],["El título","«LA MERELLE, & LE CERF VOLANT»."]]},"feldcards":{"title":"Partida de cartas en una mesa al aire libre (estereografía)","artist":"Anónimo","date":"1850–1880","place":"Desconocido (sello de una casa de Groninga al dorso)","game":"Naipes","medium":"Copia a la albúmina (estereografía)","size":"8,5 × 17,0 cm","credit":"","p":["Una estereografía de una familia o un grupo de amigos jugando a las cartas en la mesa de un jardín, con hiedra sobre un enrejado. Al dorso lleva el sello de Feldbrugge & Co., de Groninga (Países Bajos), probablemente la tienda o el editor que la vendía.","El hombre barbudo de la izquierda alza una carta para estamparla en la mesa. Un hombre con la cabeza apoyada en la mano, un muchacho con sus naipes, un anciano de pelo blanco y una mujer que mira desde atrás completan el instante. Como todos debían estar quietos, la escena probablemente se posó."],"spots":[["La carta en alto","La carta que alza el barbudo."],["Sobre la mesa","Cartas ya jugadas."],["Las cartas del muchacho","Las que sostiene el muchacho de espaldas."],["El anciano","El hombre de pelo blanco sentado a la derecha."],["La mujer que mira","De pie detrás, sigue la partida."],["La silla bordada","Una silla delante tapizada con tela floreada."]]},"tempel":{"title":"Tablero de juego «El templo de la fortuna»","artist":"Anónimo","date":"1816","place":"Países Bajos","game":"Juego de recorrido con dados","medium":"Xilografía con texto tipográfico","size":"43,0 × 48,5 cm","credit":"","p":["Una hoja de juego con casillas del 1 al 74 en espiral. En el centro se alza un templo redondo junto al mar; la hoja de reglas que se conserva en la misma colección lo llama «El templo de la fortuna» y habla de un juego de tirar, es decir, de dados.","Casi todas las casillas son círculos vacíos, pero aquí y allá hay rosas, espinas, dados, una verja, una barca de paso y otros dibujos, y palabras como «LEER GELD» (dinero de aprendizaje), «DOMHEID» (necedad) y «WYSHEID» (sabiduría). Probablemente es un juego moralizante que pasa por buenas y malas conductas camino del templo."],"spots":[["El templo de la fortuna","El templo junto al mar, en el centro: la casilla 74, la meta."],["La casilla 1","La salida, abajo a la izquierda."],["Dinero de aprendizaje","Una casilla con «LEER GELD»."],["Los dados","Dos dados dibujados en la fila superior."],["La barca","El dibujo «OVER HAAL» (paso de barca) en la fila inferior."],["Necedad y sabiduría","Las palabras «DOMHEID» y «WYSHEID» a la derecha."]]},"verkeer":{"title":"Tablero en miniatura de verkeer","artist":"Anónimo","date":"1690–1710","place":"Países Bajos (Ámsterdam)","game":"Verkeer (pariente del backgammon), ajedrez, tres en raya de nueve piezas","medium":"Nogal con taraceas de olivo, ébano, boj y hueso; herrajes de cobre","size":"Cerrado 5,8 × 5,8 cm (abierto 11,6 cm)","credit":"","p":["Un tablero de juego de apenas seis centímetros de lado que se abre como una caja. Por fuera tiene un tablero de ajedrez y otro de molino; por dentro, uno de verkeer, pariente holandés del backgammon. Se cierra con bisagras de cobre y un ganchito.","Dentro quedan aún un dado, nueve fichas de hueso, cuatro de ébano y tres monedillas. Su número de inventario indica que probablemente pertenece al mobiliario de la casa de muñecas de Petronella Oortman. Aunque diminuto, su taracea es esmerada y está hecho como un tablero de verdad."],"spots":[["El dado","Un dado no mayor que un grano de arroz."],["Las fichas de hueso","Fichas blancas redondas de hueso."],["Las fichas de ébano","Fichas negras de ébano."],["Las puntas","Triángulos taraceados en madera clara y oscura."],["Las bisagras","Bisagras de cobre para plegarlo."],["El gancho","Un ganchito de cobre para cerrarlo."]]},"silverbd":{"title":"Tablero de plata en miniatura con fichas","artist":"Frederik van Strant II","date":"1739","place":"Países Bajos (Ámsterdam)","game":"Damas, molino","medium":"Plata","size":"5,4 × 5,4 cm","credit":"","p":["Un tablero de plata de apenas 5,4 centímetros de lado: 64 casillas, un borde levantado y una anilla para colgarlo. Las casillas oscuras están grabadas con líneas finas, y el otro lado lleva grabadas las líneas del molino.","Lleva la marca de la ciudad de Ámsterdam, la letra de fecha E de 1739 y la marca del platero Frederik van Strant II. Con él se conservan quince fichas de damas, ocho con una flor y siete con un círculo. Probablemente era una miniatura de plata para una casa de muñecas o una vitrina."],"spots":[["Fichas con flor","Fichas estampadas con una flor."],["Fichas con círculo","Fichas marcadas con un círculo."],["La anilla","Una anilla en la esquina del tablero."],["Casillas grabadas","Casillas oscuras con líneas finas."],["Casillas lisas","Casillas claras, lisas y pulidas."],["El borde","El borde levantado alrededor."]]},"schaak1550":{"title":"Juego de ajedrez con piezas a caballo","artist":"Anónimo","date":"1550","place":"Alemania","game":"Ajedrez","medium":"Boj y madera de conífera","size":"Pieza mayor 10,5 cm de alto","credit":"","p":["Cada pieza se alza sobre un pie torneado rodeado de una barandilla de florones, con jinetes y caballos tallados. Reyes y reinas montan caballos o mulas, como si salieran de caza.","Según el registro del museo, el rey negro monta un caballo encabritado que pisa un dragón y lleva al cuello una cadena que recuerda la orden del Toisón de Oro, quizá para señalarlo como Carlos V. Una reina monta a mujeriegas una mula con un halcón en la mano. A la derecha, una pieza burlesca muestra a un mono a lomos de un hombre."],"spots":[["El rey","Un rey coronado y barbado, a caballo."],["La reina","Una reina a mujeriegas sobre una mula, con un halcón."],["La pieza del mono","Un mono a lomos de un hombre."],["Una pieza burlesca","A la izquierda, un hombre montado sobre otro."],["Las criaturas","Dragones y bestias bajo los cascos."],["Los pies","Pies torneados rodeados de florones."]]},"kraaij":{"title":"Hombres y mujeres jugando a un juego de tablero en un salón","artist":"Anónimo","date":"1900–1910","place":"Probablemente Países Bajos","game":"Backgammon","medium":"Copia al colodión de ennegrecimiento directo","size":"8,0 × 11,1 cm","credit":"","p":["Una página de un álbum familiar que también contiene fotos de los comerciantes de vino Kraaij & Co., Burdeos–Ámsterdam. En un salón con lámpara de araña, hombres y mujeres, quizá familia y amigos, se sientan a una mesa.","Sobre la mesa hay un tablero en forma de caja plegable abierto, y las mujeres de cada lado sostienen un cubilete. El registro del museo dice «un juego de tablero», pero por la caja y los cubiletes probablemente es backgammon. Cerca hay tazas de café y al fondo una jaula: una velada tranquila en casa."],"spots":[["El tablero en caja","Una caja plegable abierta como tablero."],["El cubilete izquierdo","El de la mujer con gafas."],["El cubilete derecho","La mujer del vestido de lunares a punto de tirar."],["La jaula","Una jaula sobre un pie, al fondo."],["La lámpara","Lámparas con tulipas de vidrio colgadas del techo."],["El hombre de pie","A la derecha, mira la partida."]]},"braekel":{"title":"Anciano y anciana jugando a las damas","artist":"Ferdinand De Braekeleer (I)","date":"1862","place":"Bélgica (Amberes)","game":"Damas","medium":"Aguafuerte","size":"21,8 × 16,5 cm","credit":"","p":["Un aguafuerte del pintor de Amberes De Braekeleer (1792–1883), firmado abajo a la izquierda «Ferdinand De Braekeleer Antwerpen 1862». En una vieja cocina con chimenea, un anciano y una anciana se sientan a una mesita.","Hay fichas redondas en el tablero; él toma una y ella abre la mano como si replicara. En el suelo hay un sombrero y también algunas fichas caídas. En el estante hay platos, y por la ventana se ven casas."],"spots":[["Tablero y fichas","El tablero y las fichas redondas sobre la mesa."],["El anciano","Inclinado, toma una ficha."],["La anciana","Con toca, gesticula al hablar."],["El sombrero","El sombrero del anciano en el suelo."],["La firma","«Ferdinand De Braekeleer Antwerpen 1862»."],["Los platos","Grandes platos en el estante sobre la chimenea."]]},"billiard":{"title":"Billar","artist":"Según H. W. Bunbury (grabador anónimo)","date":"1780","place":"Inglaterra (Londres)","game":"Billar","medium":"Aguafuerte y punteado","size":"30,0 × 39,1 cm","credit":"","p":["Un grabado según el caricaturista inglés Henry William Bunbury, publicado en Londres en 1780 por Watson & Dickinson. Según el museo es el número cuatro de una serie.","Dos hombres juegan al billar mientras los demás miran conteniendo el aliento. Uno se inclina sobre la mesa para tirar; otro lleva el taco al hombro. En la pared hay un taquero y dos esferas redondas para tantear. El museo señala que la mesa parece triangular."],"spots":[["Mesa y bolas","La mesa con paño y sus bolas."],["El que apunta","Inclinado sobre la mesa para jugar."],["El del taco","Espera con su largo taco."],["Las esferas del tanteo","Dos esferas en la pared, probablemente para llevar la cuenta."],["El taquero","Una fila de tacos contra la pared."],["Los dos que ríen","Dos mirones a la derecha, riéndose juntos."]]},"baizi":{"title":"Cien niños (detalle)","artist":"Xu Yanghong","date":"Siglo XVIII","place":"China","game":"Weiqi (go)","medium":"Rollo horizontal; tinta (y color suave) sobre papel","size":"29,8 × 526 cm (rollo entero)","credit":"","p":["Una escena de go recortada de un rollo de más de cinco metros del pintor profesional chino Xu Yanghong. En un jardín, cien niños juegan, hacen música, leen y escriben. Los «cien niños» son un tema importante del arte asiático: simbolizan la fecundidad y la prosperidad familiar.","El rollo es conocido también por una copia posterior del maestro japonés Tani Bunchō, que está en el mismo museo. Junto a hojas de banano y una roca de letrado, los niños rodean un tablero de go sobre un pie bajo; dos juegan con cuencos de piedras en la mano y los demás miran."],"spots":[["El tablero","Un tablero de go sobre un pie bajo, con piedras."],["El niño que juega","De chaqueta azul, con la mano en el cuenco."],["El otro jugador","De blanco, inclinado sobre el tablero."],["Manos en la cabeza","Un niño que mira desde atrás."],["La roca de letrado","Una gran roca llena de agujeros."],["El abanico de plumas","Un niño a la izquierda con un abanico de plumas."]]},"schenkcards":{"title":"Dos mujeres chinas jugando a las cartas","artist":"Pieter Schenk (II)","date":"1727–1775","place":"Países Bajos (tema: China)","game":"Naipes","medium":"Aguafuerte","size":"16,5 × 26,2 cm","credit":"","p":["Una lámina de la primera parte de «Chinos de nueva invención», álbum de figuras y paisajes de estilo chino publicado por el grabador y editor de Ámsterdam Pieter Schenk el Joven. Es chinoiserie, el gusto por una China imaginada que estuvo de moda en Europa.","Según el registro del museo, dos mujeres chinas juegan a las cartas en un jardín mientras otra llega por la derecha con una bandeja llena. Los naipes de la mesa parecen europeos. A la izquierda descansa un conejo sobre un pie, y en el río hay un velero."],"spots":[["Los naipes","Cartas extendidas en la mesa; parecen europeas."],["La mujer de la izquierda","Con cartas en la mano, mira a su compañera."],["La mujer de la derecha","Deja una carta sobre la mesa."],["La mujer de la bandeja","Trae una bandeja llena de comida."],["El conejo","Descansa sobre un pie a la izquierda."],["El velero","Un barco en el río."]]},"gosaucer":{"title":"Plato con figuras jugando al go","artist":"Anónimo","date":"1725–1735","place":"China","game":"Go (weiqi)","medium":"Porcelana con esmaltes sobre cubierta y dorado","size":"Diámetro 16,4 cm","credit":"","p":["Un plato chino pintado con los suaves colores sobre cubierta llamados familia rosa. Por debajo lleva una marca de un pincel, un cetro ruyi y una barra de tinta en un doble círculo. Los registros del museo describen las figuras como un hombre y una mujer jugando al go y también como tres mujeres, dos de ellas jugando.","En una habitación hay un tablero de go sobre una mesa; dos jugadores, frente a frente, colocan piedras, y un tercero mira de pie detrás. En la mesa hay cuencos amarillos para las piedras; detrás, un pie con un jarrón de flores, y a la derecha un gran tibor azul."],"spots":[["El tablero","Un tablero de go con piedras sobre la mesa."],["El jugador de la izquierda","De morado claro, apoyado en la mesa."],["El jugador de la derecha","De rosa, colocando una piedra."],["El que mira","De pie detrás, observando."],["El jarrón","Un jarrón de flores sobre un pie."],["El tibor azul","Una gran vasija a la derecha."]]},"cheetham":{"title":"Una pequeña partida de cartas (en Rusia)","artist":"Anónimo","date":"1903–1904","place":"Rusia","game":"Naipes","medium":"Copia a la gelatina de ennegrecimiento directo","size":"9,2 × 11,5 cm","credit":"","p":["Del álbum de la familia inglesa Cheetham, que vivió en Rusia; en el soporte se lee en inglés «a little card-party». El museo señala que probablemente son amigos ingleses que visitaban a Joseph Cheetham.","En una habitación empapelada, tres personas se sientan a una mesa con mantel de flores, con los naipes abiertos. Hay dos candeleros sobre la mesa, y la mujer del centro ríe mientras despliega su mano. Probablemente fue un rato distendido con amigos de su tierra en un país lejano."],"spots":[["Las cartas del de la izquierda","La mano del hombre barbudo."],["Las cartas de la mujer","La mujer del centro abre sus naipes en abanico."],["El de la derecha","Inclinado, con naipes en la mano."],["Los candeleros","Dos candeleros sobre la mesa."],["El mantel","Un gran mantel con flores y motivos."],["La inscripción","«a little card-party» en el soporte."]]},"problem":{"title":"El problema (estereografía)","artist":"Anónimo","date":"1852–1863","place":"Desconocido","game":"Ajedrez","medium":"Estereografía coloreada","size":"8,4 × 17,4 cm","credit":"","p":["El título inglés es «The Problem». Dos figuras con pelucas blancas y trajes de estilo dieciochesco juegan al ajedrez en una mesa ornamentada, en un par coloreado de fotografías estereoscópicas. Al dorso está escrito a mano «Simons».","El más joven se sujeta las mejillas con ambas manos y mira fijamente el tablero, mientras el mayor de enfrente sonríe con picardía. Probablemente es una escena teatral preparada, en la que se ve de un vistazo quién tiene el problema. Un perro está tumbado a sus pies."],"spots":[["Tablero y piezas","El tablero y las piezas en la mesa ornamentada."],["El jugador apurado","Con la cabeza entre las manos, mira el tablero."],["El que sonríe","El mayor de casaca azul, sonriendo."],["El perro","Un perro tumbado a sus pies."],["La cortina roja","La cortina coloreada del fondo."],["La segunda imagen","La vista derecha; con estereoscopio gana profundidad."]]},"tarocco":{"title":"Diez cartas de una baraja de tarot","artist":"Anónimo (probablemente según Giuseppe Maria Mitelli)","date":"1660–1718","place":"Italia (Bolonia)","game":"Tarocchi (juegos de cartas con triunfos)","medium":"Aguafuerte y buril, en parte coloreado a mano en marrón claro","size":"Diez cartas sobre un soporte","credit":"","p":["Diez cartas de una baraja de tarot boloñesa, pegadas una junto a otra en un soporte. El tarot no se usó al principio para adivinar, sino para juegos de cartas con triunfos. Arriba a la izquierda hay una carta de título; el museo sugiere que su retrato podría ser del artista Mitelli.","La fila de arriba muestra cuatro figuras, entre ellas un hombre coronado y un jinete; la de abajo, del seis al diez del palo de oros, cada carta con tantas monedas como su número. Las líneas impresas llevan en parte un lavado marrón claro."],"spots":[["La carta de título","Arriba a la izquierda: un retrato enmarcado y una inscripción."],["El hombre coronado","Una figura coronada con cetro."],["La mujer de pie","Una mujer coronada con una copa."],["El jinete","Una carta con una figura a caballo."],["Diez de oros","Abajo a la izquierda: diez monedas."],["Seis de oros","Abajo a la derecha: seis monedas."]]},"kindtegel":{"title":"Azulejos con escenas de niños jugando","artist":"Anónimo","date":"1680–1730","place":"Países Bajos","game":"Juegos infantiles (zancos, columpio y más)","medium":"Loza estannífera (azulejos de Delft), pintada en azul","size":"107 × 80 cm (48 azulejos)","credit":"","p":["Un paño de cuarenta y ocho azulejos, ocho de alto por seis de ancho. Cada uno muestra a dos niños jugando, pintados en pequeño en azul, con un adorno llamado «araña» en cada esquina.","Uno anda en zancos, otro es empujado en un columpio, otros se agachan sobre algo en el suelo: cada azulejo muestra un juego distinto. Estos azulejos de «juegos de niños» eran muy queridos en los Países Bajos y probablemente se colocaban en las paredes de cocinas y alrededor de las chimeneas."],"spots":[["Los zancos","Un niño en zancos."],["El columpio","Un niño al que empujan en un columpio."],["Un juego en el suelo","Niños agachados jugando con algo en el suelo."],["Las arañas","Los pequeños adornos de las esquinas."],["Cuarenta y ocho azulejos","Ocho filas de seis azulejos."],["El último azulejo","El azulejo de la esquina inferior derecha."]]},"dammolen":{"title":"Tablero en miniatura de damas y molino","artist":"Anónimo","date":"1740–1760","place":"Países Bajos (Ámsterdam)","game":"Damas, molino","medium":"Nogal con pasta de relleno clara","size":"4,2 × 4,0 × 1,5 cm","credit":"","p":["Un tablerito de nogal de unos cuatro centímetros. Casi cuadrado y con borde levantado, por un lado sirve de tablero de damas y por el otro de molino.","En la cara de damas, las casillas se tallaron y rellenaron con una pasta clara para formar el ajedrezado sobre la madera; en la de molino, las líneas grabadas se rellenaron con la misma pasta. Tan pequeño, probablemente se hizo para una casa de muñecas."],"spots":[["Casillas rellenas","Casillas talladas y rellenas de pasta clara."],["Casillas de madera","Casillas que dejan ver el nogal."],["El borde","El borde levantado alrededor."],["La esquina cercana","La esquina más próxima."],["El grosor","El canto del tablero, de 1,5 cm."],["La fila del fondo","La fila de casillas del fondo."]]},"karelpiece":{"title":"Ficha de damas con retrato de Carlomagno (media)","artist":"Anónimo","date":"1525–1575","place":"Alemania (Núremberg)","game":"Damas o tablas","medium":"Boj","size":"Diámetro 5,3 cm","credit":"","p":["Una cara de una ficha de damas tallada en boj. En el centro, un perfil rodeado de una corona de laurel; alrededor, la inscripción «CAROLVS. MAGNVS. IMPER. AVGVST.» (Carlomagno, emperador).","El museo guarda más de una docena de fichas iguales, cada una con un emperador o emperatriz de la antigua Roma a la Edad Media: Tiberio, Agripina, Luis el Piadoso, Otón y otros. Probablemente era un juego de lujo concebido como una galería de soberanos."],"spots":[["El perfil","El perfil de Carlomagno dentro de una corona de laurel."],["La corona","El anillo de laurel en torno al retrato."],["CAROLVS","Las palabras «CAROLVS. MAGNVS» arriba."],["AVGVST","Las palabras «IMPER. AVGVST» a la izquierda."],["La estrella","Una estrellita que separa la inscripción."],["El borde","El borde escalonado de la ficha."]]},"vdberge":{"title":"El juego holandés, ¡la buena vida! (Naipes)","artist":"Pieter van den Berge (diseño y edición)","date":"1694–1737","place":"Países Bajos (Ámsterdam)","game":"Naipes","medium":"Aguafuerte entintado à la poupée en rojo, azul y verde","size":"27,3 × 17,0 cm","credit":"","p":["Una sátira del grabador y editor de Ámsterdam Van den Berge, titulada «LE JEU HOLLANDOIS. LA BELLE VIE!». Según el museo, unos hombres juegan a las cartas en una taberna mientras unos diablos, junto a un hombre que suspira alzando su copa y bajo la mesa, le ganan el dinero.","En el verso neerlandés de abajo, el calavera despreocupado se lamenta de que peleas de perros y de gallos, naipes y dados le han fundido el dinero. A ambos lados, dos diablos lo tientan en alemán a divertirse con dados y cartas. El cuadro del fondo muestra también peleas de perros y gallos."],"spots":[["El de la copa","El calavera de gran peluca, alzando su copa."],["Las cartas","Naipes abiertos en la mano del hombre."],["El diablo de la izquierda","Un diablo que sonríe detrás de él."],["El diablo bajo la mesa","Recoge las monedas caídas al suelo."],["El cuadro de peleas","Una pintura de peleas de perros y gallos."],["Título y verso","«LE JEU HOLLANDOIS» y el lamento del calavera."]]},"crespi":{"title":"Niños jugando a los dados","artist":"Giuseppe Maria Crespi","date":"1675–1747","place":"Italia","game":"Dados","medium":"Aguafuerte","size":"22,5 × 15,1 cm","credit":"","p":["Un aguafuerte del pintor boloñés Crespi, grabado de su propia mano. Según el museo, cuatro niños juegan a los dados en la calle, y debajo se añade un verso italiano de tres líneas.","Un niño agachado acaba de tirar los dados en el suelo mientras los otros tres miran. El verso habla de huesos (dados) y números, de un juego breve y de dinero que mengua; probablemente añade una advertencia contra el juego incluso a un pasatiempo infantil."],"spots":[["Los dados","Pequeños dados en el suelo."],["El niño agachado","Acaba de tirar los dados."],["El niño de pie","Mira la tirada desde arriba."],["El niño de la derecha","Sentado en el suelo, observa."],["El niño de atrás","Asoma detrás de los otros."],["El verso","Tres líneas de verso italiano."]]},"epinal":{"title":"El gran juego de la oca (Épinal)","artist":"Pellerin & Cie (Épinal)","date":"1791–1900","place":"Francia (Épinal)","game":"Juego de la oca (carrera)","medium":"Xilografía coloreada en amarillo, rojo, verde y azul; texto tipográfico","size":"39,8 × 59,0 cm","credit":"","p":["Una hoja en color de la imprenta Pellerin de Épinal, en el este de Francia, encabezada en francés «GRAND JEU DE L’OIE». Según el museo, una espiral de 63 casillas muestra ocas, otros animales y figuras, con el título neerlandés «GANZENBORD!» y las reglas impresas en el centro.","Según las reglas, se tiran dos dados, y caer en una oca permite avanzar otro tanto. El puente del 6 lleva al 12, la posada del 19 cuesta dos turnos, en el pozo (31) se espera a que llegue otro, el laberinto (42) devuelve al 30 y la muerte (58) a la salida. Hay que llegar al 63 exacto para ganar. A ambos lados hay fichas para recortar."],"spots":[["63: la oca","La meta, el 63: una oca en un estanque."],["Las reglas","Las reglas neerlandesas en el centro."],["Fichas para recortar","Fichas redondas numeradas a ambos lados."],["El título","«GRAND JEU DE L’OIE» arriba."],["Niños jugando","Niños jugando en la esquina inferior izquierda."],["El editor","«PELLERIN & Cie» arriba a la izquierda."]]},"matham":{"title":"Pareja jugando al chaquete","artist":"Jacob Matham (editor), versos de Simon Sovius","date":"1621","place":"Países Bajos (Haarlem)","game":"Chaquete (pariente del backgammon)","medium":"Grabado a buril","size":"17,9 × 20,0 cm","credit":"","p":["La tercera estampa de una serie de cuatro publicada por el grabador y editor de Haarlem Matham. Según el museo, una pareja elegantemente vestida juega al chaquete con dinero en una mesita; la bolsa está sobre la mesa y la dama tiene los dados en la mano.","Las largas puntas y las fichas claras y oscuras del tablero están grabadas con nitidez. Debajo hay versos en latín y neerlandés; el neerlandés advierte que no solo el exceso de bebida despierta pensamientos impuros, sino que el juego y los dados van contra todo provecho. Detrás, un muchacho alza una copa de vino."],"spots":[["El tablero","Un tablero de chaquete con puntas y fichas."],["El hombre que mueve","El del sombrero alarga la mano sobre el tablero."],["La dama de los dados","Con gran gorguera, sostiene los dados."],["El muchacho de la copa","Alza una copa de vino detrás."],["La bolsa","La bolsa de las apuestas sobre la mesa."],["Los versos","Versos de advertencia en latín y neerlandés."]]},"jardin":{"title":"Tres hombres jugando a las cartas en una mesa de jardín, con un mirón (Francia)","artist":"Anónimo (un fotógrafo aficionado francés)","date":"1900–1910","place":"Francia","game":"Naipes","medium":"Copia a la albúmina","size":"11,8 × 17,2 cm","credit":"","p":["Del álbum de un fotógrafo aficionado francés, que también contiene fotos de una familia, de la destilería Delizy & Doistau, del ejército y de lugares de interés de Francia.","A la sombra de un jardín de grava, tres hombres juegan a las cartas en una mesita mientras un anciano de barba blanca mira de pie detrás. Hay naipes sobre la mesa y el del canotier estudia su mano. Probablemente es un rato tranquilo entre familia o amigos."],"spots":[["Naipes en la mesa","Cartas jugadas sobre la mesa."],["El mirón","El anciano de barba blanca, de pie detrás."],["El del canotier","En el centro, estudia su mano."],["El de la derecha","Con chaqueta oscura y naipes."],["El de la izquierda","Con chaqueta clara."],["El jardín","La grava y los arbustos del jardín."]]},"lamplight":{"title":"Personas jugando a las cartas (bajo la lámpara)","artist":"Anónimo","date":"1900–1910","place":"Desconocido","game":"Naipes","medium":"Copia a la gelatina de plata","size":"7,5 × 10,0 cm","credit":"","p":["Una pequeña fotografía de un álbum, titulada por el museo «Personas jugando a las cartas». No se conocen ni el fotógrafo ni el lugar.","A la luz de un quinqué colgado del techo, una mujer de vestido a rayas, una niña y unos muchachos se sientan a una mesa con mantel de flecos, con los naipes abiertos en abanico. Fotografiar en una habitación oscura debió de ser difícil; probablemente se quiso captar una velada familiar."],"spots":[["El mantel de flecos","Un mantel estampado con flecos."],["El quinqué","Una lámpara de aceite colgada del techo."],["La mujer de rayas","Sentada con vestido blanco a rayas."],["Las cartas de la mujer","Los naipes que sostiene en abanico."],["Las cartas de la niña","La niña del centro abre su mano."],["El muchacho de la derecha","Inclinado, con naipes."]]},"borduur":{"title":"Tablero bordado de mesa de juego con una partida de cartas","artist":"Anónimo","date":"1700–1725","place":"Desconocido","game":"Naipes","medium":"Punto grueso y petit point en lana y seda de colores","size":"100 × 185 cm","credit":"","p":["Bordado del tablero de una mesa de juego plegable, en lana y seda de muchos colores, combinando el punto grueso y el petit point. Dentro de una forma de esquinas achaflanadas corre un marco de volutas y flores.","En el paisaje central, dos damas y un caballero juegan a las cartas en torno a una mesa. Según el registro del museo, sobre la mesa hay una bolsa, cartas y otros útiles de juego. Una mesa para jugar a las cartas, adornada, como corresponde, con una partida de cartas."],"spots":[["La mesa","La mesa verde con la bolsa y las cartas."],["El caballero","Un hombre con sombrero, sentado a la izquierda."],["La dama del centro","Una dama sentada tras la mesa."],["La dama de la derecha","Una dama vestida de azul."],["Los árboles","Árboles tras las figuras."],["El marco","Un marco de volutas y flores."]]},"piquet":{"title":"Paño estampado con un juego de piquet","artist":"Anónimo","date":"1725–1750","place":"Desconocido","game":"Piquet (juego de naipes)","medium":"Lino estampado en rojo y morado","size":"73,0 × 82,5 cm","credit":"","p":["Un paño de lino para mesa de juego, estampado entero en rojo y morado con los útiles de un juego de cartas. El registro del museo lo describe también como pañuelo.","Naipes de piquet —que se juega con 32 cartas del siete al as— se esparcen por la orla y el centro, con una bolsa en medio y fichas alrededor. Las figuras son del patrón de París, con nombres como César, Argine y Hogier."],"spots":[["La bolsa","La bolsa de las apuestas, en el centro."],["Las figuras","Reyes y reinas del patrón de París."],["Las fichas","Fichas redondas."],["La orla de naipes","Una banda de cartas alrededor del paño."],["Mazos boca abajo","Mazos que muestran el dorso."],["El paquete sellado","Un paquete de naipes sellado, abajo a la derecha."]]},"schaakglas":{"title":"Copa grabada con dos hombres jugando al ajedrez","artist":"Anónimo","date":"1815–1830","place":"Desconocido","game":"Ajedrez","medium":"Vidrio incoloro transparente, grabado a la rueda","size":"Alto 13,7 cm","credit":"","p":["Una copa de vidrio transparente con pie, con dibujo y letras tallados con una pequeña rueda giratoria. Ante una mesita con dos velas, dos hombres se enfrentan sobre un tablero de ajedrez.","El de la izquierda, con anteojos, fuma en pipa; el de la derecha se inclina sobre el tablero, y hay una copa de vino en la mesa. Alrededor corre una inscripción en francés: saber los movimientos es cosa sencilla; saber el juego es fruto del genio."],"spots":[["El tablero","El tablero con sus piezas."],["El de la pipa","A la izquierda, con anteojos y pipa."],["El que se inclina","A la derecha, mirando el tablero."],["Las velas","Dos velas tras el tablero."],["La copa de vino","Una copa sobre la mesa."],["La inscripción","Palabras grabadas en francés."]]},"arlequin":{"title":"El juego de lotería de Arlequín","artist":"Anónimo (editado por Mindermann & Co.)","date":"1818–1845","place":"Países Bajos (Ámsterdam)","game":"Lotería / juego de recorrido","medium":"Grabado coloreado a mano, pegado a cartón","size":"Desconocido","credit":"","p":["Una hoja de juego cuyo tablero es la figura misma de Arlequín, de pie con las piernas abiertas. Casillas cuadradas numeradas del 1 al 32 recorren su traje verde y el espacio entre sus piernas. Abajo van el título «Arlequin’s Lotto-Spel» y el nombre de Mindermann & Co., de Ámsterdam.","Lleva una máscara de redecilla y sostiene un sombrero y algo parecido a una espada de madera. Algunas casillas llevan «HW» o «P». El grabado coloreado a mano se pegó a un cartón, probablemente para servir de tablero."],"spots":[["La máscara de red","La red que le cubre la cara."],["La casilla 1","La salida, bajo su pierna izquierda."],["Una casilla HW","Una casilla marcada «HW»."],["P 32","La casilla 32, marcada «P»."],["El título","«Arlequin’s Lotto-Spel» al pie."],["El sombrero","El sombrero de su mano derecha."]]},"vicaire":{"title":"La partida del vicario","artist":"René Gayant (según la lámina)","date":"1888–1893","place":"Francia","game":"Naipes","medium":"Fototipia (según el museo)","size":"10,4 × 15,6 cm","credit":"","p":["Una lámina del Bulletin du Photo-Club de Paris, titulada «La partie du Vicaire» (la partida del vicario). En el margen se lee «Phototype René Gayant» y «Héliogravure Lemercier», así que la foto es probablemente de Gayant y la impresión de Lemercier. Estaba encuadernada de lado en el libro.","En una cocina con ollas y sartenes colgadas, un cura de sotana negra se sienta a la mesa mirando sus naipes, y el hombre de enfrente también tiene cartas. Un hombre con gorra apoya la barbilla en la mano y un joven, con la mano en la oreja, sigue la partida. La luz y la composición, como de cuadro, encajan con un club dedicado a la fotografía artística."],"spots":[["Los naipes del cura","Las cartas que mira el cura."],["El cura","Con sotana negra y alzacuello blanco."],["El hombre con cartas","De pelo rizado, mira su mano."],["El joven que mira","Con la mano en la mejilla, sigue la partida."],["El hombre de la gorra","Con la barbilla en la mano."],["La pared de la cocina","Ollas y cucharones colgados."]]},"israels":{"title":"Los ajedrecistas","artist":"Isaac Israels","date":"1875–1922","place":"Países Bajos","game":"Ajedrez","medium":"Pastel","size":"40,0 × 57,5 cm","credit":"","p":["Un pastel del pintor neerlandés Isaac Israels (1865–1934), conocido por sus escenas rápidas y vivas de la vida urbana de Ámsterdam. En una habitación con una ventana luminosa, unos hombres rodean un tablero de ajedrez.","Los dos de delante apoyan la mejilla o el mentón en la mano, mirando fijamente el tablero, mientras un hombre con gorra se inclina detrás. Las piezas no están dibujadas con detalle, sino puestas como toques de color; parece pasar un largo rato de reflexión."],"spots":[["Tablero y piezas","El tablero; las piezas son toques de color."],["El jugador de la izquierda","La mejilla en la mano, mira el tablero."],["El jugador de la derecha","El mentón en la mano, piensa."],["El de la gorra","Se inclina desde atrás."],["La ventana","La ventana luminosa a la izquierda."],["La silla","Una silla a la derecha."]]},"louisxi":{"title":"Luis XI y su hija Ana de Beaujeu","artist":"Adrien Joseph Verhoeven-Ball","date":"1866","place":"Bélgica (Amberes)","game":"Ajedrez","medium":"Estampa (probablemente aguafuerte)","size":"26,4 × 31,3 cm","credit":"","p":["El pintor de Amberes Verhoeven-Ball dibujó y grabó él mismo esta estampa («pinx et sculp», abajo). El título del museo es «Luis XI y su hija Ana de Beaujeu juegan al ajedrez». Una línea de abajo menciona la segunda exposición de la Asociación de Artistas de Amberes.","Luis XI, rey de Francia en el siglo XV, se sienta a la mesa con un manto de piel, mientras su hija Ana, con la barbilla en la mano, estudia el tablero. Sobre la mesa hay piezas y un frutero, un perro yace en el suelo y detrás hay un guardia armado. Probablemente es una escena imaginada de padre e hija históricos."],"spots":[["Tablero y piezas","El tablero y las piezas sobre la mesa."],["Luis XI","El rey con sombrero y manto de piel."],["Ana","Su hija, la barbilla en la mano."],["El perro dormido","Un perro esbelto tendido en el suelo."],["El guardia","Un soldado armado en la penumbra."],["El título","«LOUIS XI ET SA FILLE ANNE DE BEAU-JEU»."]]},"bruining":{"title":"Monjes jugando a las damas","artist":"Tieleman Cato Bruining","date":"1750–1850","place":"Países Bajos","game":"Damas","medium":"Aguafuerte","size":"20,6 × 16,8 cm","credit":"","p":["Un aguafuerte del grabador neerlandés Bruining, con la inscripción abajo a la izquierda «T. Bruining inv. et fecit aqua fort» (lo ideó y grabó). Según el museo, dos monjes juegan a las damas en una mesa.","Detrás de ellos están un tercer monje y un diablo vestido con hábito. Junto a la mesa está la Muerte, también disfrazada de monje, con la guadaña escondida a la espalda. Los monjes están tan absortos en el juego que no notan a los intrusos."],"spots":[["El tablero","El damero y las fichas sobre la mesa."],["La Muerte","Con hábito, esconde la guadaña a la espalda."],["Los dos de atrás","Un tercer monje y el diablo con hábito."],["El jugador de la izquierda","Un monje inclinado sobre el tablero."],["El jugador de la derecha","Un monje que piensa, con los brazos en la mesa."],["La firma","«T. Bruining inv. et fecit aqua fort»."]]},"vanvliet":{"title":"Jugadores de chaquete a la luz de una vela","artist":"Jan Gillisz. van Vliet","date":"1631–1634","place":"Países Bajos (Leiden)","game":"Chaquete (pariente del backgammon)","medium":"Aguafuerte y buril","size":"15,2 × 13,4 cm","credit":"","p":["Una estampa de Van Vliet, que trabajó en Leiden junto a Rembrandt. Según el museo, dos figuras juegan al chaquete en una habitación oscura con una cama con dosel a la izquierda, y a la derecha hay un hombre y una mujer.","Un hombre de negro se inclina mucho sobre el tablero, de espaldas a nosotros, mientras su rival ríe con la mano en el borde del tablero. Las puntas y las fichas se ven con claridad. La fuente de luz no se ve, pero solo el tablero y las caras están iluminados; probablemente es una partida nocturna."],"spots":[["El tablero","Un tablero de chaquete con puntas y fichas."],["El jugador que ríe","Ríe con la mano en el borde del tablero."],["El hombre inclinado","De negro y de espaldas, inclinado sobre el tablero."],["El del sombrero","De pie detrás, con sombrero de ala ancha."],["La figura con gorguera","A la derecha, con una mano alzada."],["Las cortinas de la cama","Cortinas de la cama con dosel a la izquierda."]]},"hermans":{"title":"Dos mujeres y una niña ante un tablero de ajedrez","artist":"François Hermans (estudio)","date":"1857–1895","place":"Países Bajos (Róterdam)","game":"Ajedrez","medium":"Copia a la albúmina (carte de visite)","size":"10,1 × 6,2 cm","credit":"","p":["Una fotografía de formato carte de visite de un álbum familiar, con el nombre del estudio impreso al dorso: «François Hermans / Hang 421 / Rotterdam». Probablemente era un retrato de recuerdo familiar hecho en el estudio.","Sobre una mesita redonda hay un tablero de ajedrez; la mujer de la izquierda toca una pieza y la de la derecha apoya la mejilla en la mano, pensativa. Entre ambas, una niña de pie nos mira fijamente. Las tres debieron de permanecer inmóviles durante la larga exposición."],"spots":[["El tablero","Tablero y piezas sobre la mesa redonda."],["La mano que mueve","La mujer de la izquierda toca una pieza."],["La niña","De pie tras el tablero, nos mira."],["La mujer pensativa","La de la derecha, mano en la mejilla."],["El escabel","Un escabel redondo en el suelo."],["La ventana","Una ventana de celosía al fondo a la derecha."]]},"norimberg":{"title":"Ficha de damas con una vista de Núremberg","artist":"Anónimo","date":"1690","place":"Alemania (Núremberg)","game":"Damas o tablas","medium":"Boj","size":"Diámetro 5,4 cm, grosor 1,5 cm","credit":"","p":["Una ficha de boj tallada en relieve con una vista de Núremberg, sus torres y su castillo. Arriba corre «SVB AQVILAE ROMANAE ALIS QVIESCO» (descanso bajo las alas del águila romana), y abajo «NORIBERGA VRBIVM REGINA» (Núremberg, reina de las ciudades).","Según el registro del museo, la otra cara lleva los retratos del emperador José I y de los siete electores. Probablemente talla en una pieza de juego el orgullo de Núremberg, ciudad imperial del Sacro Imperio."],"spots":[["La vista","Núremberg con sus agujas y murallas."],["El lema de arriba","«SVB AQVILAE ROMANAE…»."],["El lema de abajo","«NORIBERGA VRBIVM REGINA»."],["El emblema","La pequeña divisa de lo alto."],["El castillo","El castillo en la altura, a la derecha."],["El borde","El borde escalonado de la ficha."]]},"toovenaar":{"title":"El Mago: nuevo y divertido juego infantil","artist":"Anónimo","date":"1856","place":"Países Bajos (Ámsterdam)","game":"Juego de recorrido (pariente de la oca)","medium":"Litografía con texto tipográfico, coloreada a mano","size":"44,5 × 53,5 cm","credit":"","p":["Un juego de recorrido titulado «DE TOOVENAAR» (El mago), «nuevo y divertido juego infantil», con casillas del 1 al 63 en espiral. En el centro, un mago ante una mesa con calavera, cáliz, luna y estrellas, con seres diabólicos detrás; diablos con cabeza de bestia ocupan las esquinas.","Las reglas impresas en el centro se parecen mucho a las de la oca. Se tiran dos dados: seis y tres en la primera tirada llevan al 26, cinco y cuatro al 53. El mago cuenta otra vez como una oca; el puente cuesta uno, la posada dos y un turno, el laberinto del 42 hace retroceder tres, y la Muerte obliga a pagar y empezar de nuevo."],"spots":[["El mago","El mago ante su mesa, en el centro."],["Título y reglas","El título «DE TOOVENAAR» y las reglas."],["La meta 63","La última casilla de la espiral."],["Los diablos","Diablos con cabeza de bestia en las esquinas."],["El recorrido exterior","Casillas con dibujos alrededor del borde."],["La mesa","Calavera y cáliz sobre la mesa."]]},"fichesdoos":{"title":"Caja de marfil con fichas","artist":"Mariaval le Jeune","date":"1725","place":"Francia (París)","game":"Fichas para juegos de cartas","medium":"Marfil","size":"2 × 8 × 6 cm","credit":"","p":["Una cajita de marfil del tamaño de la palma para las fichas que en los juegos de cartas sustituían al dinero. En la tapa, una mujer coronada con cetro se sienta en las nubes junto a un pavo real, con dos escudos de armas; por el pavo real es probablemente la diosa Juno.","Según el registro del museo, la tapa lleva la inscripción «Mariaval le Jeune a Rouen fecit», y por debajo hay un águila y pájaros, uno de ellos colgado de una horca. Dentro quedan diecinueve fichas grandes y seis pequeñas pintadas con insectos y flores."],"spots":[["La mujer coronada","Una mujer coronada sentada en las nubes."],["El pavo real","Un pavo real a sus pies."],["Los escudos","Dos escudos de armas arriba a la derecha."],["El pajarito","Un pájaro en una percha a su lado."],["Las nubes","Las nubes que la sostienen."],["El borde de la tapa","El borde y el cierre de la tapa."]]},"vuilmere":{"title":"La madre del artista jugando a las damas","artist":"Édouard Vuillard","date":"h. 1890–91","place":"Francia","game":"Damas","medium":"Pastel con grafito, difuminado y borrado sobre papel avitelado marfil","size":"37,5 × 30,5 cm","credit":"","p":["Un pastel del pintor francés Vuillard con su madre. Vuillard vivía con ella y dibujó una y otra vez escenas de su casa, donde ella trabajaba como modista. Está firmado «E Vuillard» abajo a la derecha.","Dos figuras de negro se sientan ante una mesa de un naranja intenso, y la de delante sostiene un tablero de damas. Según el título del museo, aquí aparece la madre del artista. Dentro de una línea oval negra, personas y muebles se funden en masas de color y forma."],"spots":[["El tablero","Un tablero de casillas blancas y negras."],["La figura del fondo","Una figura de negro al otro lado de la mesa."],["La figura de delante","La que sostiene el tablero."],["La mesa naranja","Un estallido de color en el cuadro."],["La pared estampada","Un papel de líneas en remolino."],["La firma","«E Vuillard» abajo a la derecha."]]},"dewitte":{"title":"Dos hombres jugando al ajedrez","artist":"Adrien de Witte","date":"1877","place":"Bélgica","game":"Ajedrez","medium":"Probablemente aguafuerte","size":"13,2 × 12,5 cm","credit":"","p":["Un pequeño grabado del pintor y grabador belga de Witte (1850–1935), de Lieja. Según el museo, la bibliografía (Clercx, 1981) supone que los dos ajedrecistas son Terme y Zeyen.","En una mesa con mantel, un joven mira el tablero con los brazos cruzados, mientras el hombre mayor de enfrente apoya la cabeza en la mano, pensativo. Detrás del tablero se ve lo que parece una caja para las piezas. En la habitación oscura, de trazos finos, transcurre una partida tranquila."],"spots":[["Tablero y piezas","El tablero y las piezas sobre la mesa."],["La caja","Lo que parece una caja detrás del tablero."],["El joven","Con los brazos cruzados, mira el tablero."],["El hombre mayor","La cabeza en la mano, piensa."],["El mantel","El paño sobre la mesa."],["La silla","El respaldo de una silla curvada a la izquierda."]]},"orphans":{"title":"Los huérfanos (niños jugando a las damas)","artist":"Charles Rolls, según W. Gill","date":"1810–1834","place":"Inglaterra","game":"Damas","medium":"Estampa (grabado a buril)","size":"22,6 × 13,9 cm","credit":"","p":["Una estampa titulada abajo «THE ORPHANS» (Los huérfanos), con la inscripción «Painted by W. Gill, Engraved by C. Rolls». Según el museo pudo usarse en The Keepsake, un libro de regalo anual publicado en Londres.","En una cocina, una niña y un niño juegan a las damas en un tablero puesto sobre un barril. Detrás, una mujer borda, y al fondo hay lo que el museo llama un telar. El título sugiere que son huérfanos acogidos por la mujer."],"spots":[["El tablero","El damero y las fichas sobre un barril."],["La niña","Se inclina para mirar el tablero."],["El niño","Mueve una ficha."],["La mujer que borda","Borda detrás de ellos."],["La jarra","Una jarra en el suelo."],["El título","«THE ORPHANS» abajo."]]},"richelieu":{"title":"Luis XIII y Richelieu","artist":"Jan Frederik Christiaan Reckleben","date":"1850","place":"Países Bajos (Ámsterdam)","game":"Ajedrez","medium":"Grabado en acero","size":"24,2 × 29,6 cm","credit":"","p":["Un grabado en acero del grabador de Ámsterdam Reckleben, encabezado «1850. NEDERLANDSCH MUSEUM. Pl. II.». Según el museo pudo ilustrar un artículo de la revista Nederlandsch Museum.","Ante una gran chimenea, el rey Luis XIII de Francia y su ministro el cardenal Richelieu juegan al ajedrez mientras un grupo de hombres mira. El cardenal, sentado a la izquierda, alarga la mano hacia una pieza; el rey, con sombrero de plumas, se recuesta tranquilo. En el extremo izquierdo hay un monje de brazos cruzados."],"spots":[["El tablero","Tablero y piezas sobre la mesa con tapete."],["Richelieu","El cardenal alarga la mano hacia una pieza."],["Luis XIII","El rey con sombrero de plumas."],["El monje","De brazos cruzados, mira desde la izquierda."],["Los cortesanos","Hombres reunidos a la derecha."],["El título","«LODEWIJK DE XIII EN RICHELIEU» abajo."]]},"coster":{"title":"Hombres jugando al chaquete a la luz de una vela (según De Coster)","artist":"Según Adam de Coster (grabado por Vorsterman)","date":"1619–1628","place":"Flandes","game":"Chaquete (pariente del backgammon)","medium":"Grabado a buril","size":"37,1 × 35,1 cm","credit":"","p":["Una estampa según un cuadro del pintor flamenco de escenas a la luz de la vela Adam de Coster, con las inscripciones «A. De Coster pi.» y «Vorsterman» abajo. Según el museo, dos hombres de pie ante una mesa juegan al chaquete a la luz de una vela.","A la izquierda mira un hombre con pipa; a la derecha una muchacha toca el laúd y un hombre con gorro señala la vela. El jugador de delante, de espaldas, se inclina sobre la mesa mientras su rival tiene la mano sobre el tablero. Una sola vela ilumina la escena y destaca solo caras y manos."],"spots":[["El tablero","El tablero sobre la mesa, medio en sombra."],["La vela","La única vela que ilumina la escena."],["El jugador de espaldas","Inclinado sobre la mesa."],["El rival","Con la mano sobre el tablero."],["El fumador","Mira a la izquierda con la pipa en la boca."],["La tañedora de laúd","Una muchacha que toca el laúd a la derecha."]]},"kiebitz":{"title":"Kiebitz (el mirón)","artist":"Hans Watzek","date":"1894","place":"Probablemente Austria","game":"Naipes","medium":"Autotipia (ilustración de libro)","size":"10,0 × 12,1 cm","credit":"","p":["Una fotografía del fotógrafo artístico vienés Hans Watzek, firmada «HANS WATZEK 94» arriba a la derecha. Está impresa en autotipia en un libro cuyo titulillo dice «¿Es la fotografía un arte?».","El título alemán «Kiebitz» significa avefría, y en jerga designa al mirón que se entromete en una partida de cartas. Un hombre con sombrero estudia sus naipes mientras el de delante, con una larga pipa, mira por encima. El tono granuloso y pictórico es propio de la fotografía artística de la época, que quería acercarse a la pintura."],"spots":[["Los naipes","La mano que estudia el hombre de la derecha."],["El jugador","Con bombín y pipa en la boca."],["El mirón","El de la larga pipa, probablemente el «Kiebitz» del título."],["La jarra","Una jarra de vidrio sobre la mesa."],["La firma","«HANS WATZEK 94» arriba a la derecha."],["El pie","«HANS WATZEK. — KIEBITZ.» debajo."]]},"evdvelde":{"title":"Jugadores de chaquete en el jardín de un castillo","artist":"Esaias van de Velde","date":"1630","place":"Países Bajos","game":"Chaquete (pariente del backgammon)","medium":"Tiza negra y aguada gris","size":"18,5 × 30,1 cm","credit":"","p":["Un dibujo de Esaias van de Velde (1587–1630), pionero de la pintura de género y de paisaje holandesa, firmado «E.V.VELDE» abajo a la derecha. Según el museo, una elegante compañía juega al chaquete en una mesa del jardín de un castillo.","Un hombre inclinado sobre el tablero y otro sentado se enfrentan, con damas mirando detrás. Delante a la izquierda hay una enfriadera de vino con dos jarras; más allá, un muchacho y un pavo real junto a una fuente. Es una elegante tarde de juego al aire libre."],"spots":[["El tablero","El tablero de chaquete sobre la mesa."],["El hombre inclinado","Con sombrero, se inclina sobre el tablero."],["El hombre sentado","Con las piernas cruzadas, frente al tablero."],["Las damas que miran","De pie detrás, siguen la partida."],["Pavo real y muchacho","Un pavo real y un muchacho junto a la fuente."],["La enfriadera","Una enfriadera con dos jarras delante a la izquierda."]]},"cooghen":{"title":"Dos hombres jugando al chaquete","artist":"Leendert van der Cooghen","date":"1666","place":"Países Bajos (Haarlem)","game":"Chaquete (pariente del backgammon)","medium":"Aguafuerte","size":"9,3 × 15,6 cm","credit":"","p":["Un aguafuerte del pintor de Haarlem Van der Cooghen, con el año «1666» rayado en la pared sobre el tablero. Según el museo, dos hombres juegan al chaquete en una mesa de taberna mientras una mujer mira por encima del hombro del de la izquierda.","El hombre mayor de la izquierda lleva una chaqueta ribeteada de piel y sostiene una copa alta; el joven de la derecha lleva un llamativo sombrero con plumas. Un monito está sentado en la ventana. El borde y las puntas del tablero se ven con claridad."],"spots":[["El tablero","El tablero de chaquete sobre la mesa."],["El hombre mayor","Con chaqueta ribeteada de piel."],["La copa","La copa alta en la mano del mayor."],["La mujer que mira","Mira por encima del hombro del de la izquierda."],["El monito","Un monito en la ventana."],["El del sombrero de plumas","El joven jugador con sombrero emplumado."]]},"roybet":{"title":"El jugador de ajedrez","artist":"Ferdinand Roybet","date":"1875","place":"Francia (París)","game":"Ajedrez","medium":"Probablemente aguafuerte","size":"26,1 × 19,6 cm","credit":"","p":["Una estampa dibujada y grabada por el pintor francés Roybet, aficionado a pintar caballeros del siglo XVII («F. Roybet del. et sc.» abajo a la izquierda). Debajo va el título «LE JOUEUR D’ÉCHECS» y, a la derecha, el nombre del editor Cadart.","Un hombre con sombrero de plumas y espada al cinto se sienta de lado en un banco y alarga la mano hacia las piezas. No se ve a ningún rival; parece meditar la posición a solas. En el estante de detrás hay una jarra de cerveza, un jarro y copas."],"spots":[["Tablero y piezas","El tablero y las piezas sobre el banco."],["El caballero","El hombre del sombrero de plumas."],["La mano que se alarga","Su mano hacia una pieza."],["La espada","Una larga espada al costado."],["Vasijas en el estante","Jarra, jarro y copas."],["El título","«LE JOUEUR D’ÉCHECS»."]]},"capot":{"title":"«San Pedro, amigo mío, ¡está usted capote!» (pintor y modelo a las cartas)","artist":"Anónimo (editado por Aubert & Cie)","date":"1838","place":"Francia (París)","game":"Naipes (probablemente piquet)","medium":"Litografía","size":"30,5 × 22,2 cm","credit":"","p":["Una litografía publicada en el diario satírico parisino Le Charivari el 9 de septiembre de 1838, número 13 de la serie «Les Artistes». El pie dice «St. Pierre, mon ami, vous êtes capot!».","Según el museo, el pintor llama «San Pedro» a su compañero de cartas porque el hombre posa para el santo del cuadro. Quedar «capote» significa perder todas las bazas en el piquet, así que el juego es probablemente el piquet."],"spots":[["Naipes en la mesa","Cartas jugadas en la mesita."],["El modelo","El hombre de pelo largo, de espaldas; su pelo y barba coinciden con el santo, así que probablemente es el modelo."],["El pintor","El hombre de la derecha con sus cartas, probablemente el pintor."],["El cuadro del santo","El santo a medio pintar en el caballete."],["El taburete","El taburete de madera del modelo."],["El pie","«St. Pierre, mon ami, vous êtes capot!»."]]},"ziacard":{"title":"Rey de tréboles (Antonio Salva, gobernador del pueblo de Zia)","artist":"Adam Clark Vroman (fotografía), Lazarus & Melzer (editor)","date":"1900","place":"Estados Unidos (Los Ángeles)","game":"Naipes","medium":"Autotipia (fotograbado de trama)","size":"8,8 × 6,3 cm","credit":"","p":["Según el registro del museo, es una carta de una baraja en caja de 53 naipes, comodín incluido, impresa en fotograbado de trama con fotografías de nativos americanos. Las fotos son de Adam Clark Vroman y la editó Lazarus & Melzer, de Los Ángeles.","En lugar de un rey dibujado, el rey de tréboles lleva el retrato de Antonio Salva, gobernador del pueblo de Zia, en Nuevo México. Debajo están impresos su nombre y su cargo, y en las esquinas, la K y el trébol. Probablemente se hizo como recuerdo para quienes visitaban el Oeste."],"spots":[["Índice de la esquina","K y trébol arriba a la izquierda, como en cualquier baraja."],["El rostro del gobernador","Antonio Salva, mirando de lado."],["El pelo largo","Melena hasta los hombros y flequillo recto."],["El pañuelo","Un paño anudado al cuello de una camisa blanca."],["Nombre y cargo","Impreso: «Antonio Salva. Governor Pueblo of Sia»."],["Índice invertido","K y trébol al revés, abajo a la derecha."]]},"gothink":{"title":"Jugando al go","artist":"Fotógrafo japonés (nombre desconocido)","date":"1887-1897","place":"Japón","game":"Go","medium":"Fotografía coloreada a mano (ilustración de libro)","size":"8,8 × 13 cm","credit":"","p":["Tomada por un fotógrafo japonés anónimo y coloreada a mano en Japón, esta foto está pegada en la página 65 de un libro en inglés sobre Japón. El pie impreso explica: «El go es un juego más difícil que el ajedrez. Llegó a Japón desde China en el siglo VIII».","Ante un tablero de go con patas, la mujer de la izquierda coloca una piedra mientras un anciano de barba blanca se lleva la mano a la cabeza, absorto. La mujer del centro observa el tablero; delante hay una bandeja de dulces y tazones de té. Probablemente se escenificó en un estudio para visitantes extranjeros."],"spots":[["El tablero","Un tablero de go con patas y piedras."],["La mano que juega","La mujer de la izquierda alarga la mano."],["El anciano pensativo","Un anciano de barba blanca, mano en la cabeza."],["La mujer que mira","Con kimono a rayas, en el centro."],["La bandeja de dulces","Dulces en una bandeja, delante."],["El cuenco de piedras","Un cuenco con tapa junto al tablero."]]},"craps":{"title":"Jugadores juveniles","artist":"Francis A. Place","date":"1888-1893","place":"Probablemente Estados Unidos","game":"Dados","medium":"Fotografía (ilustración de libro)","size":"14 × 9,9 cm","credit":"","p":["Según el registro del museo, cuatro muchachos sin identificar juegan a los dados; en el soporte figura el nombre del fotógrafo Francis A. Place. Está pegada dos páginas antes de la página 142 de un libro, con las notas impresas «copias en papel americano “Aristo”» y «hecha con el aparato de luz de magnesio Williams». Probablemente servía de muestra del papel y del flash.","Junto a una pared, con paja en el suelo, los chicos rodean una caja. Encima hay un plato de hojalata y dos dados. El de la derecha chasquea los dedos; el que está sentado en el suelo apoya la barbilla en la mano y mira. Abajo aparece rayado «COME SEV», probablemente el grito «¡ven, siete!» del craps, el juego de dados estadounidense."],"spots":[["Dos dados","Dos dados sobre la caja."],["El plato de hojalata","Un plato sobre la caja, quizá para las apuestas."],["El chasquido","El chico de la derecha chasquea los dedos hacia los dados."],["El chico sentado","En el suelo, con la barbilla en la mano."],["«COME SEV»","Letras rayadas abajo: probablemente «¡ven, siete!»."],["Letras de la caja","Letras estarcidas en el costado de la caja."]]},"bikkel":{"title":"Estudio de un hombre jugando a las tabas","artist":"Jan Baptist Weenix (posiblemente)","date":"1642–1647","place":"Italia (Roma)","game":"Tabas","medium":"Tiza negra y blanca sobre papel azul","size":"26,7 × 18,0 cm","credit":"","p":["Un dibujo a tiza negra y blanca sobre papel azul. Según el museo, es posiblemente del pintor holandés Weenix, de sus años en Roma; en otro tiempo se vendió como obra de Anthonie Palamedesz.","Un hombre con sombrero se inclina mucho mirando sus manos; a sus pies hay unos huesecillos en el suelo. Lanzar y recoger astrágalos de oveja y otros animales es un juego antiquísimo, a menudo llamado antepasado de los dados."],"spots":[["El rostro","Mira sus manos bajo el sombrero."],["Las manos","Probablemente a punto de lanzar las tabas."],["Huesos en el suelo","Pequeños huesos en el suelo."],["El zapato","El pie bien apoyado."],["La tiza blanca","Tiza blanca para las luces."],["La capa","La capa que cubre su espalda."]]},"stukken":{"title":"Diseño para piezas de ajedrez","artist":"Anónimo (Francia)","date":"1850–1875","place":"Francia","game":"Ajedrez","medium":"Pluma y tinta negra, aguada opaca blanca y rojo anaranjado sobre tiza negra, en papel azul","size":"26,5 × 20,0 cm","credit":"","p":["Un dibujo de diseño para un juego de ajedrez, de un dibujante francés desconocido. Dos filas muestran cinco tipos de pieza cada una: rey, dama, torre, una figura y caballo.","Arriba, un rey y una dama coronados y un soldado arrodillado con lanza; abajo, un rey con turbante, una dama velada y un arquero arrodillado: los dos bandos se concibieron probablemente como ejércitos de Occidente y Oriente. El blanco y el rojo anaranjado sugieren talla y brillo."],"spots":[["Rey (arriba)","Coronado, con cetro."],["Dama (arriba)","La dama coronada."],["La torre","La torre del juego."],["El lancero","Pieza arrodillada con lanza."],["El rey con turbante","El rey de la fila inferior."],["El arquero","Pieza arrodillada tensando el arco."]]},"rozetempel":{"title":"Jardín de flores, o el ameno Templo de las Rosas (tablero de dados)","artist":"Anónimo (editado por Hendrik Moolenyzer)","date":"1792–1847","place":"Países Bajos (Ámsterdam)","game":"Tablero de dados","medium":"Estampa","size":"46,1 × 39,6 cm","credit":"","p":["Un tablero de juego en hoja suelta del editor amstelodamés Moolenyzer, titulado arriba «BLOEMENHOF of VERMAKELIJKE ROZE TEMPEL» (Jardín de flores, o el ameno Templo de las Rosas).","En el centro, un jarrón de rosas dentro del «ROZE TEMPEL», rodeado de parejas de dados y flores. Probablemente se jugaba tirando dos dados y pagando o cobrando la apuesta en la flor de la tirada."],"spots":[["El título","«BLOEMENHOF of VERMAKELIJKE ROZE TEMPEL»."],["El templo","El «ROZE TEMPEL» del centro."],["Parejas de dados","Combinaciones de dos dados."],["El jarrón","Rosas en un jarrón dentro del templo."],["El tulipán","Una de las flores del círculo."],["El editor","«Te AMSTERDAM bij H. Moolenyzer»."]]},"brelan":{"title":"Le Brelan (de los Juegos de la infancia)","artist":"Claudine Stella (según Jacques Stella)","date":"1657","place":"Francia (París)","game":"Brelan (juego de tres cartas)","medium":"Grabado a buril","size":"12,0 × 14,2 cm","credit":"","p":["Una lámina de Les Jeux et plaisirs de l’enfance, álbum de 51 escenas de juegos infantiles. Sobre el verso se lee «LE BRELAN»; niños rollizos juegan a las cartas sentados en el suelo.","El verso cuenta que uno hace rodar su aro mientras los demás, amontonados, tientan la suerte con las cartas, y el que creía ganar se va más ligero. El brelan suele citarse entre los lejanos antepasados del póquer."],"spots":[["Una mano de cartas","Un niño abre sus cartas en abanico."],["Carta en el suelo","Una carta con una «A» en el suelo."],["El mirón","Un niño espía la mano desde atrás."],["El aro","Un niño hace rodar un aro con un palo."],["La torre","Una torre redonda al fondo."],["El título","«LE BRELAN» y el verso."]]},"pwkarte":{"title":"Naipe redondo con seis loros","artist":"Maestro PW de Colonia","date":"1470–1500","place":"Alemania (Colonia)","game":"Naipes (baraja redonda)","medium":"Grabado a buril","size":"Diámetro 7,0 cm","credit":"","p":["Un naipe redondo impreso a buril hace más de quinientos años. Según el museo, forma parte de una baraja de 70 cartas redondas en cinco palos: rosas, aguileñas, claveles, loros y liebres.","Cada palo tenía diez cartas numeradas del 1 al 10 y cuatro con una figura. Este es el seis de loros, con un «6» arábigo arriba y un «VI» romano abajo; seis loros rodean el adorno central."],"spots":[["El «6»","El número arábigo de arriba."],["El «VI»","El número romano de abajo."],["El loro de arriba","Un loro como posado."],["El loro que aletea","Un loro con las alas abiertas."],["El loro boca abajo","Un loro cabeza abajo."],["El adorno central","El adorno radiante del centro."]]},"nilson":{"title":"El juego de tablero (damas y tocadille)","artist":"Johann Esaias Nilson","date":"1731–1788","place":"Alemania (Augsburgo)","game":"Damas y tocadille","medium":"Aguafuerte y buril","size":"18,9 × 28,8 cm","credit":"","p":["Una estampa con marco rococó diseñada y editada por el grabador de Augsburgo Nilson, titulada arriba «Das Bretspiel» (El juego de tablero). Es la tercera de una serie de cuatro.","Según el museo, en la mesa de la izquierda un hombre y una mujer juegan a las damas, y en la de la derecha dos hombres juegan al tocadille, un juego de la familia del backgammon. El verso alemán dice que quien juega al tocadille está ansioso por ganar, y quien juega a las damas necesita todos sus sentidos."],"spots":[["El tablero de damas","En la mesa de la izquierda."],["El tablero de tocadille","En la mesita de la derecha."],["El lector","Un hombre lee una carta con la pipa en la boca."],["La mujer con loza","Lleva vajilla a la derecha."],["El parque","El parque tras el marco ornamental."],["El verso","«Wer Tocadille spielt…»."]]},"chateau":{"title":"El castillo de naipes","artist":"François Joullain (según Charles-Antoine Coypel)","date":"1725","place":"Francia (París)","game":"Naipes (castillo de naipes)","medium":"Grabado a buril","size":"23,2 × 15,8 cm","credit":"","p":["Una estampa grabada por Joullain según un diseño del pintor Coypel y editada en París por Duchange. El nombre «CH. COYPEL» aparece en un papel caído en el suelo.","Un niño bien vestido levanta un castillo de naipes sobre la mesa mientras un muchacho detrás mira con un dedo en los labios. El verso bromea con los jugadores: quien se ríe de estos niños que alzan un castillo a merced del menor viento pasaría por sabio, si nunca hubiera usado las cartas para otra cosa."],"spots":[["El castillo de naipes","Cartas apiladas en la mesa."],["Cartas en la mano","Las que sostiene el niño."],["El constructor","El niño de gorro con plumas."],["El muchacho que mira","Con un dedo en los labios."],["El papel del suelo","La hoja con «CH. COYPEL»."],["El verso","«Tel qui rit, voyant ces Enfans…»."]]},"pugillus":{"title":"Joven arruinado por los dados y dama elegante","artist":"Jacob van der Heyden (posiblemente)","date":"1608–1618","place":"Francia (Estrasburgo)","game":"Dados","medium":"Grabado a buril","size":"9,0 × 13,2 cm","credit":"","p":["Una lámina de la serie «Pugillus facetiarum iconographicarum» (un puñado de chistes en imágenes) dirigida a estudiantes; según el museo, constaba probablemente de 36 o más estampas.","A la izquierda, una dama ricamente vestida con un abanico; a la derecha, un joven harapiento se quita el sombrero y mira dos dados y una bolsa vacía en el suelo. Los lemas —más o menos «paraíso del ojo, infierno del alma, purgatorio de la bolsa» y «nunca dinero contante, siempre calzas rotas»— se burlan de los amoríos y el juego."],"spots":[["La dama elegante","Con gorro de piel y vestido largo."],["El abanico","Un abanico de plumas en su mano."],["El joven","Se quita el sombrero como saludando."],["La ropa rota","Jubón y calzas hechos jirones."],["Dados y bolsa","Dos dados y una bolsa vacía en el suelo."],["El lema","«Nunquam bar gelt, semper zerrissen hosen»."]]},"grootebroek":{"title":"La lotería de Grootebroek","artist":"Cornelis Dusart","date":"1694–1695","place":"Países Bajos (Haarlem / Ámsterdam)","game":"Lotería","medium":"Mezzotinta y buril","size":"25,1 × 19,5 cm","credit":"","p":["El 20 de agosto de 1694 un gran incendio asoló el pueblo de Grootebroek, cerca de Enkhuizen, y se celebró una lotería para las víctimas. Esta estampa de Dusart la editó en Ámsterdam Jacob Gole.","Según el museo, un hombre lleva una caldera y una carta sellada a los ganadores. El título viene a decir «mostrando con qué alegría se llevan a casa los cuantiosos premios»: un trompetero, un hombre que alza la caldera y una mujer que levanta las manos en la ventana transmiten la euforia del premio."],"spots":[["La carta sellada","Llevada a los ganadores."],["La caldera","Un hombre alza la caldera del premio."],["La trompeta","Un hombre pregona la noticia."],["La mujer en la ventana","Levanta las manos sorprendida."],["Los juerguistas","Beben y celebran a la derecha."],["El título","«Lottery van Groottenbroek»."]]},"narren":{"title":"Dos bufones jugando a los dados (del Elogio de la locura de Erasmo)","artist":"Caspar Merian (según dibujos de Hans y Ambrosius Holbein)","date":"1516 (dibujos)","place":"Suiza (Basilea)","game":"Dados","medium":"Aguafuerte","size":"5,5 × 6,0 cm","credit":"","p":["Una diminuta ilustración del Elogio de la locura de Erasmo. Los hermanos Holbein dibujaron estas escenas en 1516 en los márgenes de un ejemplar del erudito Oswald Myconius; Merian las grabó para la edición impresa en Basilea en 1676.","Un hombre con gorro de bufón con cascabeles y otro con capucha tiran los dados sobre una mesa redonda, con tres dados encima. Los pies descalzos completan la imagen de locos arrastrados por el juego."],"spots":[["Los dados","Tres dados en la mesa."],["El bufón del gorro","Se inclina a la izquierda."],["Los cascabeles","En las puntas del gorro."],["El encapuchado","Mira a su rival a la derecha."],["El cascabel de la capucha","Al final de la capucha."],["Pies descalzos","Bajo la mesa."]]},"historiespel":{"title":"El juego de la historia patria","artist":"Johannes Christiaan Bendorp","date":"1816","place":"Países Bajos (Ámsterdam)","game":"Juego de recorrido (tipo juego de la oca)","medium":"Aguafuerte y buril","size":"50,3 × 61,0 cm","credit":"","p":["Un juego de tablero por la historia neerlandesa, editado por Gartman en Ámsterdam. Según el museo sigue el esquema del juego de la oca con 80 casillas numeradas, de la 1 (la revuelta bátava) a la 80 (la escuela de navegación de Ámsterdam).","Adapta una versión de 1787, con los hechos de las casillas 70–79 sustituidos; el más reciente es de 1816, y el juego iba acompañado de una hoja explicativa aparte. Escenas de batallas y retratos de héroes llenan las casillas: una manera de aprender historia jugando."],"spots":[["Salida: casilla 1","Abajo a la izquierda."],["Meta: casilla 80","La escuela de navegación en el centro."],["El título","«VADERLANDSCH HISTORIESPEL»."],["Una casilla con retrato","Con un retrato."],["Las setenta","Casillas setenta en el anillo interior."],["El editor","«HENDRIK GARTMAN»."]]},"daumier":{"title":"Parisinos que nunca estarán bajo vigilancia policial","artist":"Honoré Daumier","date":"1847","place":"Francia (París)","game":"Damas","medium":"Litografía","size":"29,7 × 22,6 cm","credit":"","p":["Una litografía del caricaturista Daumier, publicada en el diario parisino Le Charivari el 25 de agosto de 1847. Arriba figuran el título de la serie «TOUT CE QU’ON VOUDRA» (Lo que usted quiera) y el número 12.","En una mesita, dos hombres mayores juegan a las damas mientras un tercero, con la barbilla en la mano, mira el tablero entre ambos. El pie dice «Parisinos que nunca serán puestos bajo la vigilancia de la alta policía»: probablemente una broma sobre estos ancianos inofensivos."],"spots":[["El tablero","El tablero de damas."],["El que mueve","A la izquierda, alarga la mano."],["El mirón","En medio, con la barbilla en la mano."],["El de la derecha","Mira fijamente el tablero."],["El cuadro","Un marco en la pared del fondo."],["El pie","«Parisiens qui ne seront jamais placés…»."]]},"arnauts":{"title":"Arnautas jugando a las damas","artist":"Henry Augustin Valentin (según Jean-Léon Gérôme)","date":"1856–1886","place":"Francia (París)","game":"Damas","medium":"Estampa (probablemente aguafuerte)","size":"21,7 × 27,0 cm","credit":"","p":["Una estampa de Valentin según una pintura del francés Gérôme, editada en París por Goupil & Cie, con el título «ARNAUTES JOUANT AUX DAMES» debajo. Los arnautas eran soldados albaneses al servicio del Imperio otomano.","Según el museo, dos arnautas sentados frente a frente en un banco juegan a las damas. El de la izquierda, con un traje plisado a modo de falda, juguetea con algo en las manos; el de la derecha, con una larga pipa en la boca, se inclina sobre el tablero. En la pared de la izquierda se ve la firma de Gérôme."],"spots":[["El tablero","El tablero de damas entre ambos."],["El de la izquierda","Sentado con traje plisado."],["Sus manos","Juguetean con algo."],["El de la derecha","Inclinado sobre el tablero."],["La pipa","Una larga pipa en la boca."],["La firma","La firma de Gérôme en la pared."]]},"luyken":{"title":"Turcos fumando y jugando al ajedrez","artist":"Jan Luyken","date":"1698","place":"Países Bajos (Ámsterdam / editado en Delft)","game":"Ajedrez","medium":"Aguafuerte y buril","size":"30,5 × 19,1 cm","credit":"","p":["Una ilustración grabada por Luyken para la página 136 del relato de viajes por Asia Menor de Cornelis de Bruyn (Delft, 1698). Una plancha lleva dos escenas, marcadas A arriba y B abajo.","En la escena superior seis hombres con turbante fuman largas pipas y dos de ellos juegan al ajedrez sobre la alfombra; la inferior muestra a cuatro mujeres tomando café y una sirvienta. Una hilera de babuchas queda al borde del estrado."],"spots":[["El tablero","Un tablero sobre la alfombra."],["El jugador","Alarga la mano hacia una pieza."],["El que se inclina","Mira el tablero."],["Las pipas","Largas pipas encendidas."],["Las babuchas","Calzado en fila delante."],["Árboles en las ventanas","Árboles tras las ventanas."]]},"kabinet":{"title":"Jugadores de cartas","artist":"Maestro del Gabinete de Ámsterdam","date":"1483–1487","place":"Alemania","game":"Naipes","medium":"Punta seca","size":"13,1 × 12,0 cm","credit":"","p":["Una obra maestra temprana de la punta seca —rayada directamente en el cobre con una aguja— del artista conocido como Maestro del Gabinete de Ámsterdam. Según el museo solo se conservan cuatro impresiones; las demás están en Coburgo, Múnich y Oxford.","Al aire libre, una joven elegante está sentada entre tres jóvenes y un bufón, con un naipe en el regazo. El bufón y la fuente del fondo a la derecha sugieren un jardín del amor. Delante hay un perro sentado."],"spots":[["La joven","Con un naipe en el regazo."],["El naipe","Sobre su regazo."],["El joven de la izquierda","Le habla."],["El bufón","Tendido en el suelo."],["El perro","Sentado delante."],["La fuente","Al fondo a la derecha."]]},"lievens":{"title":"Jugadores de cartas peleando y la Muerte","artist":"Jan Lievens","date":"1638","place":"Flandes (Amberes)","game":"Naipes","medium":"Aguafuerte","size":"19,7 × 25,9 cm","credit":"","p":["Un aguafuerte de Jan Lievens, joven compañero de Rembrandt, según su propia pintura, editado en Amberes por Frans van den Wyngaerde.","Según el museo, dos jugadores de cartas han llegado a las manos: el viejo de la derecha blande una jarra como arma, su rival ha volcado la mesa con los naipes y una mano con un cuchillo se alza en el aire. La Muerte interviene, agarra del cuello al de la izquierda y blande un hueso. El lema latino habla de la vanidad de las disputas humanas ante la muerte."],"spots":[["La Muerte","El esqueleto que interviene."],["El hueso","Blandido por la Muerte."],["El cuchillo","Alzado en el aire."],["La jarra","Blandida por el viejo."],["Naipes en el suelo","Cartas esparcidas."],["El lema","«Rixas atque odia…»."]]},"sorgheloos":{"title":"El juego de azar (de la historia de Sorgheloos)","artist":"Cornelis Anthonisz. (tallado y editado por Jan Ewoutsz.)","date":"1541","place":"Países Bajos (Ámsterdam)","game":"Juego de cartas por dinero","medium":"Xilografía coloreada a mano","size":"39,5 × 28,9 cm","credit":"","p":["La cuarta de seis xilografías coloreadas a mano que cuentan la ruina del despreocupado Sorgheloos. Sobre las figuras flotan cartelas con sus nombres y debajo hay dos poemas en neerlandés.","Según el museo, Sorgheloos, con el brazo sobre Weelde (Lujo), juega por dinero con el buhonero Lichte Fortune (Fortuna voluble), con Ghemack (Comodidad) a la izquierda. A la derecha entra una pareja harapienta, Armoede (Pobreza) y Pover (Miseria): la suerte va a cambiar."],"spots":[["Naipes y monedas","Sobre la mesa verde."],["Sorgheloos","El joven despreocupado."],["Weelde","La mujer en su brazo."],["Ghemack","Sentado a la izquierda."],["Lichte Fortune","El buhonero con una caja a la espalda."],["Pobreza y Miseria","La pareja que entra a la derecha."]]},"aleabelli":{"title":"El juego de la guerra (alegoría de la Guerra del Norte)","artist":"Anónimo (posiblemente Crispijn van de Passe II)","date":"1656","place":"Países Bajos","game":"Chaquete (pariente del backgammon)","medium":"Aguafuerte, buril y tipografía","size":"38,8 × 35,5 cm","credit":"","p":["Una sátira sobre la Guerra del Norte de 1656, con una hoja de texto en cuatro columnas pegada debajo. El paño de la mesa lleva la inscripción «ALEA BELLI» (el azar de la guerra).","Según el museo, el sueco y el danés juegan al chaquete, rodeados de otras figuras y de una lanza con el sombrero de «Aurea Libertas». A la derecha un marinero holandés vierte dinero en un cofre agujereado, y delante unos cerdos esperan la matanza o el embarque hacia Suecia. Al fondo, el castillo de Kronborg y la mano de Dios saliendo de un cometa."],"spots":[["El tablero","El chaquete sobre la mesa."],["ALEA BELLI","Las letras del paño."],["El sombrero de la libertad","«Aurea Libertas» en la lanza."],["El cofre agujereado","El del marinero."],["Los cerdos","En primer plano."],["El cometa","Arriba a la derecha, con la mano de Dios."]]},"shunman":{"title":"Naipes de poemas y su caja (surimono)","artist":"Kubota Shunman","date":"1806","place":"Japón (Edo)","game":"Naipes de poemas (Hyakunin isshu)","medium":"Xilografía en color (surimono)","size":"16,1 × 21,3 cm","credit":"","p":["Un surimono: estampa de lujo que une imagen y poemas, a menudo hecha como regalo. Lleva la firma de Kubota Shunman y poemas de Nakasandō, Tago no Ishibumi y Naokoto Shibaura.","Según el museo, delante de una caja de madera abierta con crisantemos blancos hay unos naipes con poetas célebres y parte de sus versos. Son de un juego de poemas basado en el Hyakunin isshu (Cien poetas, un poema cada uno), y los tres poemas de arriba a la izquierda remiten a los tres naipes representados."],"spots":[["La caja de crisantemos","Caja de madera con crisantemos."],["Los naipes","Naipes con versos."],["Un naipe de poeta","Con la figura de un poeta."],["Los tres poemas","Arriba a la izquierda."],["Firma y sello","La firma de Shunman arriba a la derecha."],["El paño","Un paño granate debajo."]]},"mitelli":{"title":"El juego de los oficios: a quién le va bien y a quién mal","artist":"Giuseppe Maria Mitelli","date":"1698","place":"Italia (Bolonia)","game":"Tablero de dados","medium":"Aguafuerte","size":"32,6 × 43,8 cm","credit":"","p":["Un juego de dados ideado y grabado por el boloñés Mitelli. El título dice que se juega con tres dados, probablemente pagando o cobrando apuestas según la tirada.","Según el museo, veinte casillas muestran oficios —músicos, un tabaquero, un vendedor de licores, un orfebre, un sombrerero, un librero, un farolero, un impresor, un marquista, un tejedor, un pintor y un escultor, entre otros—, cada uno con una frase sobre su suerte. Hay incluso una casilla para los que llevan casas de juego."],"spots":[["El título","«GIOCO DE MESTIERI…»."],["Tiradas de dados","Los dados de la casilla de los músicos."],["Los dueños de garitos","«Quelli che tengono gioco»."],["El tabaquero","Pesando tabaco."],["El impresor","La casilla «Stampatore»."],["La firma","«MITELLI… 1698»."]]},"hogarth":{"title":"La lotería","artist":"William Hogarth","date":"1721","place":"Gran Bretaña (Londres)","game":"Lotería","medium":"Estampa","size":"25,9 × 32,8 cm","credit":"","p":["Una estampa ideada y hecha por el satírico inglés Hogarth, con el título «The LOTTERY» y una explicación en inglés debajo; esta impresión lleva una traducción manuscrita al neerlandés.","Según el museo, muestra la personificación del Crédito Nacional, dioses que presentan el emblema de la lotería nacional, y virtudes y vicios ligados al juego y los sorteos. A izquierda y derecha se alzan grandes ruedas de lotería para extraer premios y blancos, y delante se mezclan afortunados y desafortunados."],"spots":[["La rueda izquierda","Una gran rueda de lotería."],["La rueda derecha","La segunda rueda."],["El Crédito Nacional","La figura entronizada en el pedestal."],["El pedestal","El gran pedestal central."],["Los eufóricos","El grupo de delante a la derecha."],["El título","«The LOTTERY»."]]},"matthieu":{"title":"Damas jugando a las damas a la luz de una vela","artist":"Georg David Matthieu","date":"1765","place":"Alemania","game":"Damas","medium":"Aguafuerte","size":"17,9 × 22,7 cm","credit":"","p":["Un aguafuerte del retratista alemán Matthieu, firmado «G. D. Matthieu 1765» abajo a la derecha. No es una taberna, sino una tranquila velada en casa.","Según el museo, tres mujeres con cofia se sientan a una mesa redonda donde arde una vela. Una sostiene un libro y mira cómo juegan a las damas las otras dos. Sobre la mesa hay también unas despabiladeras y una cajita."],"spots":[["El tablero","El tablero de damas en la mesa."],["La vela","Arde en medio de la mesa."],["Las despabiladeras","Para recortar la mecha."],["La mujer del centro","Nos mira."],["La mujer de la derecha","Con la vista baja, alarga la mano."],["La firma","«G. D. Matthieu 1765»."]]},"pillement":{"title":"Niños chinos haciendo un castillo de naipes (de los Juegos de niños chinos)","artist":"Pierre Charles Canot (según Jean Baptiste Pillement)","date":"1759","place":"Gran Bretaña (Londres) / Francia (París)","game":"Castillo de naipes","medium":"Aguafuerte","size":"42,6 × 27,3 cm","credit":"","p":["Una de las ocho láminas del «Recueil de plusieurs jeux d’enfants chinois», grabadas por Canot según diseños de Pillement, célebre por sus chinerías, y editadas en Londres y París. Son niños chinos imaginados por la moda europea de la chinoiserie.","Según el museo, arriba dos niños levantan un castillo de naipes en una mesa redonda mientras un tercero llega corriendo con un palo; abajo un niño va a caballito sobre otro y un tercero está a la izquierda. Ambas escenas van enmarcadas con cercas y follaje."],"spots":[["El castillo de naipes","Sobre la mesa redonda."],["El niño del palo","Llega corriendo."],["El pabellón","Un edificio de estilo chino detrás."],["A caballito","Un niño a espaldas de otro."],["El niño de pie","A la izquierda, abajo."],["La línea de edición","«London Published… 1759»."]]},"skating":{"title":"El juego de la pista de patinaje","artist":"Anónimo (editado por Gebroeders Koster)","date":"1870","place":"Países Bajos (Ámsterdam)","game":"Juego de recorrido (como la oca)","medium":"Litografía en color y tipografía","size":"42,6 × 57,5 cm","credit":"","p":["Un juego de tablero sobre el patinaje sobre ruedas, editado en Ámsterdam por Gebroeders Koster. Según el museo se parece al juego de la oca, con reglas en neerlandés, francés, alemán e inglés en las cuatro esquinas.","En el centro un chico y una chica en patines se dan la mano, y las casillas de alrededor muestran escenitas de gente que se desliza y se cae. Algunas casillas llevan parejas de dados, y la meta es «SKATINGRINK 52»."],"spots":[["La pareja de patinadores","El chico y la chica del centro."],["La meta","«SKATINGRINK 52»."],["Tiradas de dados","Casillas con dados."],["Los que se caen","Una escena de caídas."],["Las reglas","Texto en las esquinas."],["El editor","«GEBROEDERS KOSTER»."]]},"gavarni":{"title":"Una esposa mirando a su marido y a su amante en un juego de tablero","artist":"Paul Gavarni","date":"1837","place":"Francia (París)","game":"Juego de tablero (tipo no registrado)","medium":"Litografía","size":"31,7 × 23,3 cm","credit":"","p":["Una litografía del caricaturista Gavarni, publicada en el diario parisino Le Charivari el 20 de diciembre de 1837; es la número 2 de una serie de doce.","Según el museo, una esposa mira a su marido y a su amante jugar a un juego de tablero. El de la izquierda, con bata y fez, es probablemente el marido; el joven inclinado sobre el tablero, el amante. El pie recoge la queja del amante: pasar toda la velada jugando con un marido estúpido que te gana el dinero, se burla de ti y se va a acostar en tus narices."],"spots":[["El marido","Con bata y fez."],["El tablero","Sobre la mesa."],["El amante","Inclinado sobre el tablero."],["La esposa","De pie detrás."],["El adorno","Una figurilla bajo un fanal."],["El pie","«Faire toute la soirée…»."]]},"picart":{"title":"Una lotería en un escenario (del Gran espejo de la locura)","artist":"Bernard Picart","date":"1720–1733","place":"Países Bajos (Ámsterdam)","game":"Lotería","medium":"Aguafuerte y buril","size":"23,8 × 37,7 cm","credit":"","p":["Una de las láminas añadidas al Gran espejo de la locura, colección de sátiras sobre la fiebre especulativa de 1720; abajo a la izquierda se lee «B. Picart inv. et fec.».","Según el museo, en un escenario de una plaza se celebra una lotería y dos muchachos sacan los billetes de los bombos. Entre el público de delante estallan peleas. Una carretilla volcada, una mujer con un cesto de fruta y un perro que ladra aumentan el alboroto."],"spots":[["Los bombos","Grandes bombos en el escenario."],["El sorteo","Figuras en el escenario."],["La pelea","Gente que forcejea delante."],["El caído","Junto a la escalera y la carretilla."],["El perro","Abajo a la derecha."],["La firma","«B. Picart inv. et fec.»."]]},"unigenitus":{"title":"El juego de la oca de la bula Unigenitus","artist":"Anónimo (según una estampa francesa)","date":"1724","place":"Países Bajos","game":"Juego de la oca","medium":"Aguafuerte y buril","size":"46,0 × 58,5 cm","credit":"","p":["Una sátira sobre las disputas por la bula Unigenitus (1713) del papa Clemente XI, en forma de juego de la oca, hecha en los Países Bajos según una estampa francesa anónima. El título lo llama «el juego de la Constitución, tan extraño como desconocido, embrollado de cabeza a cola y de principio a fin».","Según el museo, el tablero tiene 63 casillas, con las reglas generales en el centro y catorce estrofas de seis versos en las dos pilastras laterales. Sobre cada columna hay ocas con collares de crucecitas y mitras de obispo."],"spots":[["El título","«Dit ’s ’t Constitutie spel…»."],["Las reglas","«Het Spel van de Constitutie» en el centro."],["Ocas con mitra (izq.)","Sobre la columna izquierda."],["Ocas con mitra (der.)","Sobre la columna derecha."],["Los versos","En las pilastras."],["Las casillas","Casillas con figuras y escenas."]]},"bles":{"title":"Hombre jugando al ajedrez (estudio)","artist":"David Bles","date":"1876","place":"Países Bajos","game":"Ajedrez","medium":"Lápiz, tiza negra, roja y blanca","size":"23,0 × 29,8 cm","credit":"","p":["Un dibujo del pintor de género holandés David Bles, firmado «DB. f» abajo a la izquierda. Abajo a la derecha se lee «Overwinnend Holland» (Holanda victoriosa) y «1796», probablemente el título de un cuadro y el año de su escena.","Un hombre hundido en su silla, con la barbilla en la mano, mira fijamente el tablero de la mesa. Quedan pocas piezas, como si la partida estuviera acabando. A la derecha hay un pequeño apunte, al parecer un segundo intento de la misma figura."],"spots":[["Tablero y piezas","El tablero sobre la mesa."],["El rostro pensativo","Con la barbilla en la mano."],["La silla","Donde está sentado."],["El apunte de la derecha","Un segundo boceto pequeño."],["La firma","«DB. f»."],["La inscripción","«Overwinnend Holland» y 1796."]]},"visscher":{"title":"El nuevo y ameno juego de la oca (con reglas)","artist":"Anónimo (editado por Claes Jansz. Visscher)","date":"1612–1652","place":"Países Bajos (Ámsterdam)","game":"Juego de la oca","medium":"Grabado a buril","size":"41,9 × 47,6 cm","credit":"","p":["Un juego de la oca editado en Ámsterdam por Visscher, titulado «HET NIEUW EN VERMAECKELYCK GHANSE-SPEL…» (el nuevo y ameno juego de la oca, y cómo se juega), con las reglas impresas en el margen.","Según el museo, algunas de las 63 casillas muestran ocas, dados, un laberinto, una fuente, un pozo y la Muerte. Las casillas se enlazan con marcos como ramas; en el óvalo central damas y caballeros hacen música, y en las esquinas hay parejas de enamorados."],"spots":[["Los músicos","Tocan en el centro."],["Meta: casilla 63","La casilla 63."],["Los dados","Una casilla con dados."],["La fuente","Una casilla con una fuente."],["Una oca","Una casilla con una oca."],["Los enamorados","Una pareja abajo a la izquierda."]]},"tombola":{"title":"Una tómbola (de Recuerdos del carnaval)","artist":"Paul Gavarni","date":"1840","place":"Francia (París)","game":"Tómbola","medium":"Litografía","size":"36,0 × 26,2 cm","credit":"","p":["Una litografía de Gavarni, publicada en el diario satírico La Caricature el 2 de febrero de 1840, con el encabezado «SOUVENIRS DU CARNAVAL».","Según el museo, tres Pierrots celebran una lotería en carnaval. El Pierrot de gafas alza un objeto largo y fino mientras se agolpan mujeres enmascaradas. El pie, «UNA TÓMBOLA. ¡El número 45 ha ganado… una vela!», hace reír con lo mísero del premio."],"spots":[["El premio alzado","Un objeto largo en alto."],["El Pierrot de gafas","Anuncia el número."],["El otro Pierrot","Con gorro, a la derecha."],["El Pierrot niño","El pequeño del centro."],["Las enmascaradas","Se agolpan."],["El pie","«Le Nº 45 a gagné… une chandelle !»."]]},"patriotten":{"title":"El juego de dados político neerlandés (tablero contra los Patriotas)","artist":"Anónimo","date":"1793","place":"Países Bajos","game":"Juego de recorrido con dados","medium":"Aguafuerte y buril","size":"43,0 × 52,3 cm (abierto)","credit":"","p":["Una estampa plegable en forma de juego de tablero que satiriza a los Patriotas neerlandeses, titulada «Nêerlands Staatkundich Werp Spel» (el juego de dados político de los Países Bajos). Según el museo es un estado posterior de una plancha de 1788, con el año cambiado a 1793 y el título ampliado con «los jacobinos franceses, los sans-culottes» y más.","Abierta, muestra escenas históricas y sátiras de los Patriotas en casillas numeradas del 1 al 35, en su mayoría copias reducidas de estampas anteriores. El centro es una transparencia: a contraluz aparece un Patriota ahorcado por el diablo en una horca. Arriba se alinean escudos de las provincias y un águila, probablemente la prusiana."],"spots":[["La transparencia","El centro que cambia a contraluz."],["El águila","Probablemente la prusiana."],["Los escudos","Escudos provinciales arriba."],["Una casilla satírica","Con una sátira."],["El hombre con fusil","Abajo a la izquierda."],["El jinete","A caballo abajo a la derecha."]]}};
